# Driver
# ---------------------------------------------------------------------------


@dataclass
class SootResult:
    """Per-program result of the Soot layer."""

    program_name: str
    classes: int
    app_classes: int
    library_classes: int
    methods: int
    concrete_methods: int
    units: int
    cfg_edges: int
    cg_nodes: int
    cg_edges: int
    reachable: int
    virtual_sites: int
    static_sites: int
    virtual_targets: int
    copies_propagated: int
    dead_units_removed: int
    entry_points: int
    elapsed_ms: float


class SootAnalysis:
    """Runs the whole Soot layer over one :class:`Program`."""

    def __init__(self, program: Program) -> None:
        self.program = program
        self.scene = reset_scene()
        self.scene.load_program(program)
        self.call_graph: CallGraph | None = None
        self.builder: CHACallGraphBuilder | None = None

    def run(self) -> SootResult:
        with Timer() as t:
            self.builder = CHACallGraphBuilder(self.scene)
            self.call_graph = self.builder.build()
            copies, dead = self._optimize()
        scene = self.scene
        cg = self.call_graph
        bodies = scene.methods_with_bodies()
        return SootResult(
            program_name=self.program.name,
            classes=len(scene.classes),
            app_classes=len(scene.application_classes()),
            library_classes=len(scene.library_classes()),
            methods=len(scene.methods),
            concrete_methods=len(bodies),
            units=scene.total_units(),
            cfg_edges=sum(m.body.graph.edge_count() for m in bodies),
            cg_nodes=len(cg.nodes),
            cg_edges=len(cg.edges),
            reachable=len(cg.reachable_methods()),
            virtual_sites=self.builder.virtual_sites,
            static_sites=self.builder.static_sites,
            virtual_targets=self.builder.virtual_targets,
            copies_propagated=copies,
            dead_units_removed=dead,
            entry_points=len(scene.get_entry_points()),
            elapsed_ms=t.elapsed_ms,
        )

    def _optimize(self) -> tuple[int, int]:
        """Run the transforms on clones so the original IR stays intact."""
        copies = dead = 0
        for method in self.scene.methods_with_bodies():
            work = method.body.clone()
            cp = CopyPropagation(work)
            copies += cp.apply()
            dce = DeadCodeElimination(work)
            dead += dce.apply()
            method.optimized_body = work  # type: ignore[attr-defined]
        return copies, dead


def analyze_program(program: Program) -> SootResult:
    return SootAnalysis(program).run()


def _benchmark_dir() -> str:
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), "benchmarks")


def main(argv: list[str] | None = None) -> int:
    argv = list(sys.argv[1:] if argv is None else argv)
    directory = argv[0] if argv else _benchmark_dir()
    programs = load_all_benchmarks(directory)

    print("=== Soot Analysis (Jimple IR, CHA call graph, transforms) ===")
    print(f"ANALYSIS_LAYER: soot")
    print(f"BENCHMARK_DIR: {os.path.relpath(directory, os.getcwd())}")
    print(f"PROGRAMS_ANALYZED: {len(programs)}")

    results: list[SootResult] = []
    for program in programs:
        res = analyze_program(program)
        results.append(res)
        print(f"--- {res.program_name} ---")
        print(f"{res.program_name}_CLASSES: {res.classes}")
        print(f"{res.program_name}_APP_CLASSES: {res.app_classes}")
        print(f"{res.program_name}_LIBRARY_CLASSES: {res.library_classes}")
        print(f"{res.program_name}_METHODS: {res.methods}")
        print(f"{res.program_name}_CONCRETE_METHODS: {res.concrete_methods}")
        print(f"{res.program_name}_JIMPLE_UNITS: {res.units}")
        print(f"{res.program_name}_CFG_EDGES: {res.cfg_edges}")
        print(f"{res.program_name}_ENTRY_POINTS: {res.entry_points}")
        print(f"{res.program_name}_CG_NODES: {res.cg_nodes}")
        print(f"{res.program_name}_CG_EDGES: {res.cg_edges}")
        print(f"{res.program_name}_REACHABLE_METHODS: {res.reachable}")
        print(f"{res.program_name}_COPIES_PROPAGATED: {res.copies_propagated}")
        print(f"{res.program_name}_DEAD_UNITS_REMOVED: {res.dead_units_removed}")

    print("--- totals ---")
    print(f"TOTAL_CLASSES: {sum(r.classes for r in results)}")
    print(f"TOTAL_APP_CLASSES: {sum(r.app_classes for r in results)}")
    print(f"TOTAL_LIBRARY_CLASSES: {sum(r.library_classes for r in results)}")
    print(f"TOTAL_METHODS: {sum(r.methods for r in results)}")
    print(f"TOTAL_CONCRETE_METHODS: {sum(r.concrete_methods for r in results)}")
    print(f"TOTAL_JIMPLE_UNITS: {sum(r.units for r in results)}")
    print(f"TOTAL_CFG_EDGES: {sum(r.cfg_edges for r in results)}")
    print(f"TOTAL_ENTRY_POINTS: {sum(r.entry_points for r in results)}")
    print(f"TOTAL_CG_NODES: {sum(r.cg_nodes for r in results)}")
    print(f"TOTAL_CG_EDGES: {sum(r.cg_edges for r in results)}")
    print(f"TOTAL_REACHABLE_METHODS: {sum(r.reachable for r in results)}")
    print(f"TOTAL_VIRTUAL_CALL_SITES: {sum(r.virtual_sites for r in results)}")
    print(f"TOTAL_STATIC_CALL_SITES: {sum(r.static_sites for r in results)}")
    print(f"TOTAL_VIRTUAL_TARGETS: {sum(r.virtual_targets for r in results)}")
    print(f"TOTAL_COPIES_PROPAGATED: {sum(r.copies_propagated for r in results)}")
    print(f"TOTAL_DEAD_UNITS_REMOVED: {sum(r.dead_units_removed for r in results)}")
    print(f"TOTAL_ANALYSIS_MS: {sum(r.elapsed_ms for r in results):.3f}")
    print(f"SOOT_ANALYSIS_STATUS: OK")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

toolUseResult.content:
"""
Soot-style whole-program analysis layer.

Builds a Jimple-like intermediate representation from the shared program
model and provides the core whole-program analysis utilities that the
taint analyses on top of it depend on:

  * ``JimpleBody`` / ``JimpleStmt``  -- three-address IR with def/use info
  * ``UnitGraph``                    -- intra-procedural CFG over the IR
  * ``Scene``                        -- the whole-program registry (classes,
                                        methods, hierarchy, entry points)
  * ``Hierarchy``                    -- class-hierarchy queries
  * ``CHACallGraphBuilder``          -- class-hierarchy-analysis call graph
  * ``CopyPropagation``              -- forward copy propagation transform
  * ``DeadCodeElimination``          -- unreachable-code + dead-assignment
                                        elimination

Run standalone with ``python3 soot_analysis.py`` to analyse every benchmark
under ``benchmarks/`` and emit ``KEY: VALUE`` experiment lines.
"""

from __future__ import annotations

import os
import sys
from collections import defaultdict, deque
from dataclasses import dataclass, field
from typing import Iterable, Iterator

from program_model import (
    ClassDef,
    Method,
    MethodBody,
    MethodSignature,
    Program,
    Statement,
    Type,
    Variable,
    load_all_benchmarks,
)
from utils import Timer, build_hierarchy, get_all_subclasses

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------

#: Statement kinds that transfer control without falling through.
TERMINATOR_KINDS = frozenset({"return", "throw"})

#: Statement kinds that never have an observable side effect, so a definition
#: whose result is never read may be deleted outright.
PURE_KINDS = frozenset({"assign", "new", "field_load", "identity", "nop"})

#: Primitive type names understood by the IR printer.
PRIMITIVES = frozenset(
    {"int", "float", "double", "boolean", "char", "byte", "short", "long", "void"}
)

OBJECT = "java.lang.Object"


def sub_signature(sig: MethodSignature) -> str:
    """Return the class-independent part of a signature (``ret name(args)``)."""
    return f"{sig.return_type} {sig.method_name}({','.join(sig.param_types)})"


def is_constant_token(token: str) -> bool:
    """True when ``token`` is a Jimple constant rather than a local name."""
    if not token:
        return True
    if token[0] in '"\'':
        return True
    if token in ("null", "true", "false"):
        return True
    first = token[0]
    return first.isdigit() or (first == "-" and len(token) > 1 and token[1].isdigit())


# ---------------------------------------------------------------------------
# Jimple-like IR
# ---------------------------------------------------------------------------


@dataclass
class JimpleLocal:
    """A typed local variable (Jimple locals are always typed)."""

    name: str
    type_name: str
    is_parameter: bool = False
    param_index: int = -1

    def __hash__(self) -> int:
        return hash(self.name)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, JimpleLocal):
            return NotImplemented
        return self.name == other.name

    def __str__(self) -> str:
        return self.name


@dataclass
class JimpleStmt:
    """A single Jimple unit.

    Wraps a :class:`program_model.Statement` and augments it with the
    def/use sets and the textual Jimple rendering that the rest of the
    stack relies on.
    """

    stmt_id: int
    kind: str
    raw: Statement
    method_sig: MethodSignature | None = None
    line_number: int = 0
    _defs: list[str] = field(default_factory=list)
    _uses: list[str] = field(default_factory=list)

    # -- accessors ---------------------------------------------------------
    @property
    def lhs(self) -> str | None:
        return self.raw.lhs

    @property
    def rhs(self) -> str | None:
        return self.raw.rhs

    @property
    def callee(self) -> MethodSignature | None:
        return self.raw.callee

    @property
    def args(self) -> list[str]:
        return self.raw.args

    @property
    def receiver(self) -> str | None:
        return self.raw.receiver

    @property
    def field_ref(self):
        return self.raw.field_ref

    @property
    def is_source(self) -> bool:
        return self.raw.is_source

    @property
    def is_sink(self) -> bool:
        return self.raw.is_sink

    def defs(self) -> list[str]:
        """Locals written by this unit."""
        return list(self._defs)

    def uses(self) -> list[str]:
        """Locals read by this unit."""
        return list(self._uses)

    def is_invoke(self) -> bool:
        return self.kind == "call"

    def is_terminator(self) -> bool:
        return self.kind in TERMINATOR_KINDS

    def is_branch(self) -> bool:
        return self.kind == "if"

    def has_side_effects(self) -> bool:
        """Whether removing this unit could change program behaviour."""
        if self.kind not in PURE_KINDS:
            return True
        return self.is_source or self.is_sink

    # -- rendering ---------------------------------------------------------
    def to_jimple(self) -> str:
        """Render the unit in Soot's Jimple concrete syntax."""
        k, r = self.kind, self.raw
        if k == "identity":
            return f"{r.lhs} := {r.rhs}"
        if k == "assign":
            return f"{r.lhs} = {r.rhs}"
        if k == "new":
            return f"{r.lhs} = new {r.rhs}"
        if k == "field_load":
            f_ = r.field_ref
            return f"{r.lhs} = {f_.base}.<{f_.declaring_class}: {f_.field_type.name} {f_.field_name}>"
        if k == "field_store":
            f_ = r.field_ref
            return f"{f_.base}.<{f_.declaring_class}: {f_.field_type.name} {f_.field_name}> = {r.rhs}"
        if k == "call":
            invoke = self._render_invoke()
            return f"{r.lhs} = {invoke}" if r.lhs else invoke
        if k == "return":
            return f"return {r.rhs}" if r.rhs else "return"
        if k == "if":
            return f"if {r.condition} goto {r.true_target}"
        if k == "throw":
            return f"throw {r.rhs}"
        return "nop"

    def _render_invoke(self) -> str:
        r = self.raw
        sig = r.callee.full_signature() if r.callee else "<unknown>"
        arglist = ", ".join(r.args)
        if r.receiver:
            return f"virtualinvoke {r.receiver}.{sig}({arglist})"
        return f"staticinvoke {sig}({arglist})"

    def __str__(self) -> str:
        return self.to_jimple()


class JimpleBody:
    """The Jimple body of a single method: locals, units and the CFG."""

    def __init__(
        self,
        signature: MethodSignature,
        locals_: list[JimpleLocal],
        units: list[JimpleStmt],
        this_local: str | None = None,
        param_locals: list[str] | None = None,
    ) -> None:
        self.signature = signature
        self.locals = locals_
        self.units = units
        self.this_local = this_local
        self.param_locals = list(param_locals or [])
        self.local_names = {l.name for l in locals_}
        self._by_id = {u.stmt_id: u for u in units}
        self.graph = UnitGraph(self)

    # -- queries -----------------------------------------------------------
    def unit_by_id(self, stmt_id: int) -> JimpleStmt | None:
        return self._by_id.get(stmt_id)

    def local_by_name(self, name: str) -> JimpleLocal | None:
        for l in self.locals:
            if l.name == name:
                return l
        return None

    def is_local(self, token: str | None) -> bool:
        return token is not None and token in self.local_names

    def param_index_of(self, name: str) -> int:
        try:
            return self.param_locals.index(name)
        except ValueError:
            return -1

    def __iter__(self) -> Iterator[JimpleStmt]:
        return iter(self.units)

    def __len__(self) -> int:
        return len(self.units)

    # -- maintenance -------------------------------------------------------
    def rebuild(self) -> None:
        """Recompute the id index and CFG after units have been mutated."""
        self._by_id = {u.stmt_id: u for u in self.units}
        self.graph = UnitGraph(self)

    def clone(self) -> "JimpleBody":
        """Deep-enough copy so transforms never disturb the original IR."""
        import copy as _copy

        units = []
        for u in self.units:
            dup = JimpleStmt(
                stmt_id=u.stmt_id,
                kind=u.kind,
                raw=_copy.deepcopy(u.raw),
                method_sig=u.method_sig,
                line_number=u.line_number,
                _defs=list(u._defs),
                _uses=list(u._uses),
            )
            units.append(dup)
        return JimpleBody(
            self.signature,
            [JimpleLocal(l.name, l.type_name, l.is_parameter, l.param_index) for l in self.locals],
            units,
            self.this_local,
            list(self.param_locals),
        )

    def to_jimple(self) -> str:
        lines = [f"{self.signature.full_signature()} {{"]
        for l in self.locals:
            lines.append(f"    {l.type_name} {l.name};")
        if self.locals:
            lines.append("")
        for u in self.units:
            lines.append(f"    [{u.stmt_id}] {u.to_jimple()};")
        lines.append("}")
        return "\n".join(lines)


class UnitGraph:
    """Intra-procedural control-flow graph over a :class:`JimpleBody`."""

    def __init__(self, body: JimpleBody) -> None:
        self.body = body
        self.succs: dict[int, list[int]] = defaultdict(list)
        self.preds: dict[int, list[int]] = defaultdict(list)
        self._build()

    def _build(self) -> None:
        units = self.body.units
        ids = [u.stmt_id for u in units]
        index = {sid: i for i, sid in enumerate(ids)}
        valid = set(ids)
        for i, unit in enumerate(units):
            sid = unit.stmt_id
            if unit.is_terminator():
                continue
            if unit.is_branch():
                raw = unit.raw
                if raw.true_target is not None and raw.true_target in valid:
                    self._add_edge(sid, raw.true_target)
                if raw.false_target is not None:
                    if raw.false_target in valid:
                        self._add_edge(sid, raw.false_target)
                elif i + 1 < len(units):
                    self._add_edge(sid, ids[i + 1])
                continue
            if i + 1 < len(units):
                self._add_edge(sid, ids[i + 1])
        self._index = index

    def _add_edge(self, src: int, dst: int) -> None:
        if dst not in self.succs[src]:
            self.succs[src].append(dst)
        if src not in self.preds[dst]:
            self.preds[dst].append(src)

    # -- queries -----------------------------------------------------------
    def successors(self, stmt_id: int) -> list[int]:
        return list(self.succs.get(stmt_id, []))

    def predecessors(self, stmt_id: int) -> list[int]:
        return list(self.preds.get(stmt_id, []))

    def heads(self) -> list[int]:
        return [self.body.units[0].stmt_id] if self.body.units else []

    def tails(self) -> list[int]:
        return [u.stmt_id for u in self.body.units if not self.succs.get(u.stmt_id)]

    def reachable_units(self) -> set[int]:
        """Ids reachable from the body entry."""
        seen: set[int] = set()
        work = deque(self.heads())
        while work:
            cur = work.popleft()
            if cur in seen:
                continue
            seen.add(cur)
            work.extend(self.succs.get(cur, []))
        return seen

    def edge_count(self) -> int:
        return sum(len(v) for v in self.succs.values())


# ---------------------------------------------------------------------------
# IR construction
# ---------------------------------------------------------------------------


class JimpleBuilder:
    """Lowers :class:`program_model.MethodBody` into a :class:`JimpleBody`."""

    def build(self, signature: MethodSignature, body: MethodBody | None) -> JimpleBody | None:
        if body is None:
            return None
        locals_ = [self._local(v, body) for v in body.locals]
        known = {l.name for l in locals_}
        units = [self._unit(signature, s, known) for s in body.statements]
        return JimpleBody(signature, locals_, units, body.this_local, body.param_locals)

    def _local(self, var: Variable, body: MethodBody) -> JimpleLocal:
        idx = var.param_index
        is_param = var.is_parameter
        if idx < 0 and var.name in body.param_locals:
            idx = body.param_locals.index(var.name)
            is_param = True
        return JimpleLocal(var.name, var.var_type.name, is_param, idx)

    def _unit(self, sig: MethodSignature, stmt: Statement, locals_: set[str]) -> JimpleStmt:
        defs, uses = self._def_use(stmt, locals_)
        return JimpleStmt(
            stmt_id=stmt.stmt_id,
            kind=stmt.kind,
            raw=stmt,
            method_sig=sig,
            line_number=stmt.line_number,
            _defs=defs,
            _uses=uses,
        )

    def _def_use(self, stmt: Statement, locals_: set[str]) -> tuple[list[str], list[str]]:
        defs: list[str] = []
        uses: list[str] = []

        def use(tok: str | None) -> None:
            if tok and tok in locals_ and tok not in uses:
                uses.append(tok)

        k = stmt.kind
        if k in ("assign", "new", "field_load", "identity", "call") and stmt.lhs in locals_:
            if stmt.lhs:
                defs.append(stmt.lhs)

        if k == "assign":
            for v in stmt.rhs_vars:
                use(v)
            if not stmt.rhs_vars:
                use(stmt.rhs)
        elif k == "field_load":
            if stmt.field_ref:
                use(stmt.field_ref.base)
        elif k == "field_store":
            if stmt.field_ref:
                use(stmt.field_ref.base)
            for v in stmt.rhs_vars:
                use(v)
            if not stmt.rhs_vars:
                use(stmt.rhs)
        elif k == "call":
            use(stmt.receiver)
            for a in stmt.args:
                if not is_constant_token(a):
                    use(a)
        elif k == "return":
            if stmt.rhs and not is_constant_token(stmt.rhs):
                use(stmt.rhs)
        elif k == "if":
            for v in stmt.rhs_vars:
                use(v)
            if stmt.condition:
                for tok in stmt.condition.replace("(", " ").replace(")", " ").split():
                    use(tok)
        elif k == "throw":
            use(stmt.rhs)
        return defs, uses


# ---------------------------------------------------------------------------
# Scene registry
# ---------------------------------------------------------------------------


@dataclass
class SootField:
    name: str
    type_name: str
    declaring_class: str
    access: str = "public"
    is_static: bool = False

    def signature(self) -> str:
        return f"<{self.declaring_class}: {self.type_name} {self.name}>"


class SootMethod:
    """A method registered in the :class:`Scene`."""

    def __init__(self, decl: Method, declaring_class: "SootClass", body: JimpleBody | None) -> None:
        self.signature = decl.signature
        self.declaring_class = declaring_class
        self.body = body
        self.is_static = decl.is_static
        self.is_abstract = decl.is_abstract
        self.is_constructor = decl.is_constructor or decl.signature.method_name == "<init>"
        self.is_entry_point = decl.is_entry_point
        self.access = decl.access
        self.raw = decl

    @property
    def name(self) -> str:
        return self.signature.method_name

    def has_active_body(self) -> bool:
        return self.body is not None

    def sub_signature(self) -> str:
        return sub_signature(self.signature)

    def full_signature(self) -> str:
        return self.signature.full_signature()

    def is_concrete(self) -> bool:
        return not self.is_abstract and self.body is not None

    def __repr__(self) -> str:
        return f"<SootMethod {self.full_signature()}>"


class SootClass:
    """A class registered in the :class:`Scene`."""

    def __init__(self, decl: ClassDef) -> None:
        self.name = decl.name
        self.super_class = decl.super_class
        self.interfaces = list(decl.interfaces)
        self.is_interface = decl.is_interface
        self.is_abstract = decl.is_abstract
        self.is_library = decl.is_library
        self.is_android_component = decl.is_android_component
        self.component_type = decl.component_type
        self.fields = [
            SootField(
                name=f["name"],
                type_name=f.get("type", OBJECT),
                declaring_class=decl.name,
                access=f.get("access", "public"),
                is_static=f.get("is_static", False),
            )
            for f in decl.fields
        ]
        self.methods: list[SootMethod] = []
        self.raw = decl

    @property
    def is_application_class(self) -> bool:
        return not self.is_library

    def add_method(self, m: SootMethod) -> None:
        self.methods.append(m)

    def get_method_by_sub_signature(self, sub: str) -> SootMethod | None:
        for m in self.methods:
            if m.sub_signature() == sub:
                return m
        return None

    def field_by_name(self, name: str) -> SootField | None:
        for f in self.fields:
            if f.name == name:
                return f
        return None

    def __repr__(self) -> str:
        return f"<SootClass {self.name}>"


class Hierarchy:
    """Class-hierarchy queries backed by the shared ``utils`` helpers."""

    def __init__(self, scene: "Scene") -> None:
        self.scene = scene
        self.children = build_hierarchy(scene.program) if scene.program else {}

    def subclasses_of(self, class_name: str) -> set[str]:
        return get_all_subclasses(self.children, class_name)

    def direct_subclasses_of(self, class_name: str) -> list[str]:
        return sorted(self.children.get(class_name, []))

    def superclasses_of(self, class_name: str) -> list[str]:
        """Transitive supertypes (superclasses first, then interfaces)."""
        result: list[str] = []
        seen: set[str] = set()
        work = deque([class_name])
        while work:
            cur = work.popleft()
            cls = self.scene.get_class(cur)
            if cls is None:
                continue
            for parent in ([cls.super_class] if cls.super_class else []) + cls.interfaces:
                if parent and parent not in seen:
                    seen.add(parent)
                    result.append(parent)
                    work.append(parent)
        return result

    def is_subtype_of(self, sub: str, sup: str) -> bool:
        return sub == sup or sup in self.superclasses_of(sub)

    def resolve_concrete_dispatch(self, receiver_class: str, sub: str) -> SootMethod | None:
        """Virtual dispatch: find ``sub`` starting at ``receiver_class``."""
        cls = self.scene.get_class(receiver_class)
        if cls is not None:
            m = cls.get_method_by_sub_signature(sub)
            if m is not None:
                return m
        for parent in self.superclasses_of(receiver_class):
            pcls = self.scene.get_class(parent)
            if pcls is None:
                continue
            m = pcls.get_method_by_sub_signature(sub)
            if m is not None:
                return m
        return None


class Scene:
    """The whole-program registry.

    Mirrors Soot's ``Scene`` singleton: it owns every loaded class, the
    method index keyed by full signature, the class hierarchy, and the set
    of entry points the call graph is rooted at.
    """

    def __init__(self) -> None:
        self.program: Program | None = None
        self.classes: dict[str, SootClass] = {}
        self.methods: dict[str, SootMethod] = {}
        self._entry_points: list[SootMethod] = []
        self.hierarchy: Hierarchy | None = None
        self.builder = JimpleBuilder()

    # -- loading -----------------------------------------------------------
    def load_program(self, program: Program) -> "Scene":
        self.program = program
        self.classes.clear()
        self.methods.clear()
        self._entry_points.clear()
        for cls_decl in program.classes:
            sc = SootClass(cls_decl)
            self.classes[sc.name] = sc
            for m_decl in cls_decl.methods:
                jb = self.builder.build(m_decl.signature, m_decl.body)
                sm = SootMethod(m_decl, sc, jb)
                sc.add_method(sm)
                self.methods[sm.full_signature()] = sm
        self.hierarchy = Hierarchy(self)
        self._compute_entry_points(program)
        return self

    def _compute_entry_points(self, program: Program) -> None:
        seen: set[str] = set()
        for sig in program.entry_points:
            m = self.methods.get(sig.full_signature())
            if m is not None and m.full_signature() not in seen:
                seen.add(m.full_signature())
                self._entry_points.append(m)
        for key in sorted(self.methods):
            m = self.methods[key]
            if m.is_entry_point and key not in seen:
                seen.add(key)
                self._entry_points.append(m)

    # -- queries -----------------------------------------------------------
    def get_class(self, name: str) -> SootClass | None:
        return self.classes.get(name)

    def get_method(self, sig: MethodSignature | str) -> SootMethod | None:
        key = sig if isinstance(sig, str) else sig.full_signature()
        return self.methods.get(key)

    def get_entry_points(self) -> list[SootMethod]:
        return list(self._entry_points)

    def application_classes(self) -> list[SootClass]:
        return [self.classes[n] for n in sorted(self.classes) if not self.classes[n].is_library]

    def library_classes(self) -> list[SootClass]:
        return [self.classes[n] for n in sorted(self.classes) if self.classes[n].is_library]

    def android_components(self) -> list[SootClass]:
        return [
            self.classes[n]
            for n in sorted(self.classes)
            if self.classes[n].is_android_component
        ]

    def is_library_method(self, sig: MethodSignature | str) -> bool:
        m = self.get_method(sig)
        if m is not None:
            return m.declaring_class.is_library
        name = sig if isinstance(sig, str) else sig.class_name
        cls = self.get_class(name)
        return cls.is_library if cls else True

    def all_methods(self) -> list[SootMethod]:
        return [self.methods[k] for k in sorted(self.methods)]

    def methods_with_bodies(self) -> list[SootMethod]:
        return [m for m in self.all_methods() if m.has_active_body()]

    def total_units(self) -> int:
        return sum(len(m.body) for m in self.methods_with_bodies())


_SCENE: Scene | None = None


def get_scene() -> Scene:
    """Return the process-wide :class:`Scene`, creating it on first use."""
    global _SCENE
    if _SCENE is None:
        _SCENE = Scene()
    return _SCENE


def reset_scene() -> Scene:
    """Discard the current scene (benchmarks are analysed independently)."""
    global _SCENE
    _SCENE = Scene()
    return _SCENE


# ---------------------------------------------------------------------------
# Call graph
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class CallEdge:
    src_method: str
    src_stmt: int
    tgt_method: str
    kind: str  # "static" | "special" | "virtual" | "interface"

    def __str__(self) -> str:
        return f"{self.src_method}@{self.src_stmt} -{self.kind}-> {self.tgt_method}"


class CallGraph:
    """Directed multigraph of call edges keyed by full method signature."""

    def __init__(self) -> None:
        self.edges: list[CallEdge] = []
        self._out: dict[str, list[CallEdge]] = defaultdict(list)
        self._in: dict[str, list[CallEdge]] = defaultdict(list)
        self._by_site: dict[tuple[str, int], list[CallEdge]] = defaultdict(list)
        self.nodes: set[str] = set()
        self.entry_points: list[str] = []

    def add_edge(self, edge: CallEdge) -> bool:
        if edge in self._by_site[(edge.src_method, edge.src_stmt)]:
            return False
        self.edges.append(edge)
        self._out[edge.src_method].append(edge)
        self._in[edge.tgt_method].append(edge)
        self._by_site[(edge.src_method, edge.src_stmt)].append(edge)
        self.nodes.add(edge.src_method)
        self.nodes.add(edge.tgt_method)
        return True

    def edges_out_of(self, method: str) -> list[CallEdge]:
        return list(self._out.get(method, []))

    def edges_into(self, method: str) -> list[CallEdge]:
        return list(self._in.get(method, []))

    def edges_out_of_site(self, method: str, stmt_id: int) -> list[CallEdge]:
        return list(self._by_site.get((method, stmt_id), []))

    def callees_of(self, method: str) -> list[str]:
        return sorted({e.tgt_method for e in self._out.get(method, [])})

    def callers_of(self, method: str) -> list[str]:
        return sorted({e.src_method for e in self._in.get(method, [])})

    def reachable_methods(self) -> set[str]:
        """Methods transitively reachable from the entry points."""
        seen: set[str] = set()
        work = deque(self.entry_points)
        while work:
            cur = work.popleft()
            if cur in seen:
                continue
            seen.add(cur)
            for e in self._out.get(cur, []):
                work.append(e.tgt_method)
        return seen

    def __len__(self) -> int:
        return len(self.edges)


class CHACallGraphBuilder:
    """Builds a call graph using Class Hierarchy Analysis.

    Every virtual/interface call site is resolved against the full set of
    subtypes of the statically declared receiver type, which is sound (it
    over-approximates the runtime target set) and needs no points-to
    information.
    """

    def __init__(self, scene: Scene) -> None:
        self.scene = scene
        self.virtual_sites = 0
        self.static_sites = 0
        self.unresolved_sites = 0
        self.virtual_targets = 0

    def build(self) -> CallGraph:
        cg = CallGraph()
        scene = self.scene
        cg.entry_points = [m.full_signature() for m in scene.get_entry_points()]
        for sig in cg.entry_points:
            cg.nodes.add(sig)
        for method in scene.all_methods():
            cg.nodes.add(method.full_signature())
            if method.body is None:
                continue
            src = method.full_signature()
            for unit in method.body:
                if not unit.is_invoke() or unit.callee is None:
                    continue
                for edge in self._resolve_site(src, unit):
                    cg.add_edge(edge)
        return cg

    def _resolve_site(self, src: str, unit: JimpleStmt) -> list[CallEdge]:
        callee = unit.callee
        assert callee is not None
        kind = self._call_kind(unit)
        if kind in ("static", "special"):
            self.static_sites += 1
            target = self._resolve_direct(callee)
            if target is None:
                self.unresolved_sites += 1
                return []
            return [CallEdge(src, unit.stmt_id, target.full_signature(), kind)]

        self.virtual_sites += 1
        targets = self._resolve_virtual(callee)
        if not targets:
            self.unresolved_sites += 1
            return []
        self.virtual_targets += len(targets)
        return [CallEdge(src, unit.stmt_id, t, kind) for t in targets]

    def _call_kind(self, unit: JimpleStmt) -> str:
        callee = unit.callee
        assert callee is not None
        declared = self.scene.get_method(callee)
        if declared is not None and declared.is_static:
            return "static"
        if unit.receiver is None:
            return "static"
        if callee.method_name in ("<init>", "<clinit>"):
            return "special"
        if declared is not None and declared.access == "private":
            return "special"
        owner = self.scene.get_class(callee.class_name)
        if owner is not None and owner.is_interface:
            return "interface"
        return "virtual"

    def _resolve_direct(self, callee: MethodSignature) -> SootMethod | None:
        direct = self.scene.get_method(callee)
        if direct is not None:
            return direct
        assert self.scene.hierarchy is not None
        return self.scene.hierarchy.resolve_concrete_dispatch(
            callee.class_name, sub_signature(callee)
        )

    def _resolve_virtual(self, callee: MethodSignature) -> list[str]:
        """CHA: declared type resolution plus every subtype override."""
        scene = self.scene
        assert scene.hierarchy is not None
        sub = sub_signature(callee)
        targets: list[str] = []

        base = scene.hierarchy.resolve_concrete_dispatch(callee.class_name, sub)
        if base is not None and not base.is_abstract:
            targets.append(base.full_signature())

        for sub_name in sorted(scene.hierarchy.subclasses_of(callee.class_name)):
            cls = scene.get_class(sub_name)
            if cls is None or cls.is_interface:
                continue
            impl = cls.get_method_by_sub_signature(sub)
            if impl is not None and not impl.is_abstract:
                key = impl.full_signature()
                if key not in targets:
                    targets.append(key)
        return targets


# ---------------------------------------------------------------------------
# Dataflow helpers shared by the transforms
# ---------------------------------------------------------------------------


def reaching_definitions(body: JimpleBody) -> dict[int, dict[str, set[int]]]:
    """Classic forward reaching-definitions over the body's CFG.

    Returns ``{stmt_id: {local: {defining stmt ids}}}`` describing the facts
    holding *on entry* to each unit.
    """
    graph = body.graph
    entry_in: dict[int, dict[str, set[int]]] = {u.stmt_id: {} for u in body.units}
    work = deque(u.stmt_id for u in body.units)
    in_work = {u.stmt_id for u in body.units}

    def transfer(sid: int, facts: dict[str, set[int]]) -> dict[str, set[int]]:
        unit = body.unit_by_id(sid)
        out = {k: set(v) for k, v in facts.items()}
        if unit is not None:
            for d in unit.defs():
                out[d] = {sid}
        return out

    while work:
        sid = work.popleft()
        in_work.discard(sid)
        out = transfer(sid, entry_in[sid])
        for succ in graph.successors(sid):
            merged = {k: set(v) for k, v in entry_in[succ].items()}
            changed = False
            for local, defs in out.items():
                cur = merged.setdefault(local, set())
                if not defs.issubset(cur):
                    cur |= defs
                    changed = True
            if changed:
                entry_in[succ] = merged
                if succ not in in_work:
                    work.append(succ)
                    in_work.add(succ)
    return entry_in


def live_variables(body: JimpleBody) -> dict[int, set[str]]:
    """Backward live-variable analysis; returns liveness *after* each unit."""
    graph = body.graph
    live_out: dict[int, set[str]] = {u.stmt_id: set() for u in body.units}
    work = deque(u.stmt_id for u in reversed(body.units))
    in_work = {u.stmt_id for u in body.units}

    while work:
        sid = work.popleft()
        in_work.discard(sid)
        unit = body.unit_by_id(sid)
        if unit is None:
            continue
        out = set()
        for succ in graph.successors(sid):
            succ_unit = body.unit_by_id(succ)
            if succ_unit is None:
                continue
            out |= (live_out[succ] - set(succ_unit.defs())) | set(succ_unit.uses())
        if out != live_out[sid]:
            live_out[sid] = out
            for pred in graph.predecessors(sid):
                if pred not in in_work:
                    work.append(pred)
                    in_work.add(pred)
    return live_out


# ---------------------------------------------------------------------------
# Transforms
# ---------------------------------------------------------------------------


class CopyPropagation:
    """Forward copy propagation.

    For a copy ``x = y`` this rewrites later uses of ``x`` to ``y`` whenever
    ``x`` has exactly one reaching definition at that use and neither ``x``
    nor ``y`` is redefined in between. Copies of ``this``/parameter identity
    locals are left alone so the IFDS layer keeps its parameter mapping.
    """

    def __init__(self, body: JimpleBody) -> None:
        self.body = body
        self.propagated = 0

    def _copies(self) -> dict[int, tuple[str, str]]:
        out: dict[int, tuple[str, str]] = {}
        for unit in self.body.units:
            if unit.kind != "assign":
                continue
            raw = unit.raw
            if len(raw.rhs_vars) != 1:
                continue
            src = raw.rhs_vars[0]
            if raw.rhs != src or raw.lhs is None:
                continue
            if not self.body.is_local(src) or not self.body.is_local(raw.lhs):
                continue
            if raw.lhs == src:
                continue
            out[unit.stmt_id] = (raw.lhs, src)
        return out

    def apply(self) -> int:
        copies = self._copies()
        if not copies:
            return 0
        protected = set(self.body.param_locals)
        if self.body.this_local:
            protected.add(self.body.this_local)

        rd = reaching_definitions(self.body)
        for unit in self.body.units:
            defs_here = rd.get(unit.stmt_id, {})
            for used in unit.uses():
                reaching = defs_here.get(used, set())
                if len(reaching) != 1:
                    continue
                def_id = next(iter(reaching))
                if def_id not in copies:
                    continue
                lhs, src = copies[def_id]
                if lhs != used or src in protected:
                    continue
                # The source must not have been redefined since the copy.
                src_defs = defs_here.get(src, set())
                if src_defs and src_defs != rd.get(def_id, {}).get(src, set()):
                    continue
                if self._rewrite(unit, used, src):
                    self.propagated += 1
        return self.propagated

    def _rewrite(self, unit: JimpleStmt, old: str, new: str) -> bool:
        raw = unit.raw
        changed = False
        if raw.rhs_vars:
            for i, v in enumerate(raw.rhs_vars):
                if v == old:
                    raw.rhs_vars[i] = new
                    changed = True
        if raw.rhs == old:
            raw.rhs = new
            changed = True
        if raw.args:
            for i, a in enumerate(raw.args):
                if a == old:
                    raw.args[i] = new
                    changed = True
        if raw.receiver == old:
            raw.receiver = new
            changed = True
        if raw.field_ref is not None and raw.field_ref.base == old:
            raw.field_ref.base = new
            changed = True
        if changed:
            unit._uses = [new if u == old else u for u in unit._uses]
        return changed


class DeadCodeElimination:
    """Removes CFG-unreachable units and dead (never-read) definitions.

    Units with side effects -- calls, field stores, returns, branches, and
    anything flagged as a source or sink -- are always retained.
    """

    def __init__(self, body: JimpleBody) -> None:
        self.body = body
        self.removed_unreachable = 0
        self.removed_dead_assign = 0

    @property
    def removed(self) -> int:
        return self.removed_unreachable + self.removed_dead_assign

    def apply(self) -> int:
        self._remove_unreachable()
        while self._remove_dead_assignments():
            pass
        return self.removed

    def _remove_unreachable(self) -> None:
        if not self.body.units:
            return
        reachable = self.body.graph.reachable_units()
        keep = [u for u in self.body.units if u.stmt_id in reachable]
        self.removed_unreachable += len(self.body.units) - len(keep)
        if len(keep) != len(self.body.units):
            self.body.units = keep
            self.body.rebuild()

    def _remove_dead_assignments(self) -> bool:
        live_out = live_variables(self.body)
        keep: list[JimpleStmt] = []
        removed = False
        for unit in self.body.units:
            defs = unit.defs()
            if defs and not unit.has_side_effects():
                if all(d not in live_out.get(unit.stmt_id, set()) for d in defs):
                    self.removed_dead_assign += 1
                    removed = True
                    continue
            keep.append(unit)
        if removed:
            self.body.units = keep
            self.body.rebuild()
        return removed


# ---------------------------------------------------------------------------
# Driver
# ---------------------------------------------------------------------------


@dataclass
class SootResult:
    """Per-program result of the Soot layer."""

    program_name: str
    classes: int
    app_classes: int
    library_classes: int
    methods: int
    concrete_methods: int
    units: int
    cfg_edges: int
    cg_nodes: int
    cg_edges: int
    reachable: int
    virtual_sites: int
    static_sites: int
    virtual_targets: int
    copies_propagated: int
    dead_units_removed: int
    entry_points: int
    elapsed_ms: float


class SootAnalysis:
    """Runs the whole Soot layer over one :class:`Program`."""

    def __init__(self, program: Program) -> None:
        self.program = program
        self.scene = reset_scene()
        self.scene.load_program(program)
        self.call_graph: CallGraph | None = None
        self.builder: CHACallGraphBuilder | None = None

    def run(self) -> SootResult:
        with Timer() as t:
            self.builder = CHACallGraphBuilder(self.scene)
            self.call_graph = self.builder.build()
            copies, dead = self._optimize()
        scene = self.scene
        cg = self.call_graph
        bodies = scene.methods_with_bodies()
        return SootResult(
            program_name=self.program.name,
            classes=len(scene.classes),
            app_classes=len(scene.application_classes()),
            library_classes=len(scene.library_classes()),
            methods=len(scene.methods),
            concrete_methods=len(bodies),
            units=scene.total_units(),
            cfg_edges=sum(m.body.graph.edge_count() for m in bodies),
            cg_nodes=len(cg.nodes),
            cg_edges=len(cg.edges),
            reachable=len(cg.reachable_methods()),
            virtual_sites=self.builder.virtual_sites,
            static_sites=self.builder.static_sites,
            virtual_targets=self.builder.virtual_targets,
            copies_propagated=copies,
            dead_units_removed=dead,
            entry_points=len(scene.get_entry_points()),
            elapsed_ms=t.elapsed_ms,
        )

    def _optimize(self) -> tuple[int, int]:
        """Run the transforms on clones so the original IR stays intact."""
        copies = dead = 0
        for method in self.scene.methods_with_bodies():
            work = method.body.clone()
            cp = CopyPropagation(work)
            copies += cp.apply()
            dce = DeadCodeElimination(work)
            dead += dce.apply()
            method.optimized_body = work  # type: ignore[attr-defined]
        return copies, dead


def analyze_program(program: Program) -> SootResult:
    return SootAnalysis(program).run()


def _benchmark_dir() -> str:
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), "benchmarks")


def main(argv: list[str] | None = None) -> int:
    argv = list(sys.argv[1:] if argv is None else argv)
    directory = argv[0] if argv else _benchmark_dir()
    programs = load_all_benchmarks(directory)

    print("=== Soot Analysis (Jimple IR, CHA call graph, transforms) ===")
    print(f"ANALYSIS_LAYER: soot")
    print(f"BENCHMARK_DIR: {os.path.relpath(directory, os.getcwd())}")
    print(f"PROGRAMS_ANALYZED: {len(programs)}")

    results: list[SootResult] = []
    for program in programs:
        res = analyze_program(program)
        results.append(res)
        print(f"--- {res.program_name} ---")
        print(f"{res.program_name}_CLASSES: {res.classes}")
        print(f"{res.program_name}_APP_CLASSES: {res.app_classes}")
        print(f"{res.program_name}_LIBRARY_CLASSES: {res.library_classes}")
        print(f"{res.program_name}_METHODS: {res.methods}")
        print(f"{res.program_name}_CONCRETE_METHODS: {res.concrete_methods}")
        print(f"{res.program_name}_JIMPLE_UNITS: {res.units}")
        print(f"{res.program_name}_CFG_EDGES: {res.cfg_edges}")
        print(f"{res.program_name}_ENTRY_POINTS: {res.entry_points}")
        print(f"{res.program_name}_CG_NODES: {res.cg_nodes}")
        print(f"{res.program_name}_CG_EDGES: {res.cg_edges}")
        print(f"{res.program_name}_REACHABLE_METHODS: {res.reachable}")
        print(f"{res.program_name}_COPIES_PROPAGATED: {res.copies_propagated}")
        print(f"{res.program_name}_DEAD_UNITS_REMOVED: {res.dead_units_removed}")

    print("--- totals ---")
    print(f"TOTAL_CLASSES: {sum(r.classes for r in results)}")
    print(f"TOTAL_APP_CLASSES: {sum(r.app_classes for r in results)}")
    print(f"TOTAL_LIBRARY_CLASSES: {sum(r.library_classes for r in results)}")
    print(f"TOTAL_METHODS: {sum(r.methods for r in results)}")
    print(f"TOTAL_CONCRETE_METHODS: {sum(r.concrete_methods for r in results)}")
    print(f"TOTAL_JIMPLE_UNITS: {sum(r.units for r in results)}")
    print(f"TOTAL_CFG_EDGES: {sum(r.cfg_edges for r in results)}")
    print(f"TOTAL_ENTRY_POINTS: {sum(r.entry_points for r in results)}")
    print(f"TOTAL_CG_NODES: {sum(r.cg_nodes for r in results)}")
    print(f"TOTAL_CG_EDGES: {sum(r.cg_edges for r in results)}")
    print(f"TOTAL_REACHABLE_METHODS: {sum(r.reachable for r in results)}")
    print(f"TOTAL_VIRTUAL_CALL_SITES: {sum(r.virtual_sites for r in results)}")
    print(f"TOTAL_STATIC_CALL_SITES: {sum(r.static_sites for r in results)}")
    print(f"TOTAL_VIRTUAL_TARGETS: {sum(r.virtual_targets for r in results)}")
    print(f"TOTAL_COPIES_PROPAGATED: {sum(r.copies_propagated for r in results)}")
    print(f"TOTAL_DEAD_UNITS_REMOVED: {sum(r.dead_units_removed for r in results)}")
    print(f"TOTAL_ANALYSIS_MS: {sum(r.elapsed_ms for r in results):.3f}")
    print(f"SOOT_ANALYSIS_STATUS: OK")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

