"""
FlowDroid-style IFDS taint analysis.

Builds on the Jimple IR, scene registry and CHA call graph provided by
``soot_analysis`` and adds a context-sensitive, flow-sensitive,
field-sensitive taint analysis:

  * ``AccessPath``        -- base local plus a k-limited field chain
  * ``TaintAbstraction``  -- an IFDS data-flow fact (an access path plus the
                             source it originated from)
  * ``SourceSinkManager`` -- resolves sources/sinks from the program spec
  * ``AliasManager``      -- may-alias sets used to keep heap taint sound
  * ``TaintFlowFunctions``-- normal / call / return / call-to-return flows
  * ``IFDSSolver``        -- the IFDS tabulation algorithm with summaries
  * ``LifecycleModel``    -- synthesises an Android dummy-main per component
                             so taint survives across lifecycle callbacks
  * ``FlowDroidAnalysis`` -- ties it together and reports :class:`Leak` s

Run standalone with ``python3 flowdroid_analysis.py``.
"""

from __future__ import annotations

import os
import sys
from collections import defaultdict, deque
from dataclasses import dataclass, field
from typing import Iterable

from program_model import (
    MethodBody,
    MethodSignature,
    Program,
    Statement,
    Variable,
    _parse_type,
    load_all_benchmarks,
)
from soot_analysis import (
    CHACallGraphBuilder,
    CallGraph,
    JimpleBody,
    JimpleBuilder,
    JimpleStmt,
    Scene,
    SootMethod,
    is_constant_token,
    reset_scene,
)
from utils import Timer

#: Maximum number of fields tracked on an access path (FlowDroid's -al/k).
ACCESS_PATH_LENGTH = 5

#: Base name of the IFDS tautological (zero) fact.
ZERO_BASE = "<<zero>>"

#: Statement ids for synthesised dummy-main units start here so they can
#: never collide with ids coming from a benchmark body.
SYNTHETIC_ID_BASE = 100000


# ---------------------------------------------------------------------------
# Access paths
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class AccessPath:
    """A tainted memory location: a base local plus a field chain.

    ``taint_sub_fields`` marks the ``.*`` case -- the whole object is
    tainted, so reading any field of it yields tainted data.
    """

    base: str
    fields: tuple[str, ...] = ()
    taint_sub_fields: bool = True

    # -- construction ------------------------------------------------------
    @staticmethod
    def of(base: str, fields: Iterable[str] = (), taint_sub_fields: bool = True) -> "AccessPath":
        fs = tuple(fields)
        if len(fs) > ACCESS_PATH_LENGTH:
            # k-limiting: truncate and over-approximate the rest.
            return AccessPath(base, fs[:ACCESS_PATH_LENGTH], True)
        return AccessPath(base, fs, taint_sub_fields)

    def with_field(self, field_name: str) -> "AccessPath":
        return AccessPath.of(self.base, self.fields + (field_name,), self.taint_sub_fields)

    def drop_first_field(self) -> "AccessPath":
        return AccessPath.of(self.base, self.fields[1:], self.taint_sub_fields)

    def rebase(self, new_base: str) -> "AccessPath":
        return AccessPath.of(new_base, self.fields, self.taint_sub_fields)

    def prepend_to(self, base: str, field_name: str) -> "AccessPath":
        """``x`` tainted, storing into ``base.f`` yields ``base.f.<x fields>``."""
        return AccessPath.of(base, (field_name,) + self.fields, self.taint_sub_fields)

    # -- queries -----------------------------------------------------------
    @property
    def is_local_only(self) -> bool:
        return not self.fields

    def first_field(self) -> str | None:
        return self.fields[0] if self.fields else None

    def can_read_field(self, field_name: str) -> bool:
        """Whether loading ``field_name`` off this path yields tainted data."""
        if self.fields:
            return self.fields[0] == field_name
        # Whole object tainted: any field read is tainted only under .* semantics.
        return self.taint_sub_fields

    def starts_with(self, other: "AccessPath") -> bool:
        if self.base != other.base or len(self.fields) < len(other.fields):
            return False
        return self.fields[: len(other.fields)] == other.fields

    def __str__(self) -> str:
        return ".".join((self.base,) + self.fields)


# ---------------------------------------------------------------------------
# Taint facts
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class TaintAbstraction:
    """An IFDS fact: a tainted access path plus its provenance."""

    access_path: AccessPath
    source_stmt: int = -1
    source_method: str = ""
    source_api: str = ""
    source_category: str = ""
    is_alias: bool = False

    @staticmethod
    def zero() -> "TaintAbstraction":
        return ZERO

    @property
    def is_zero(self) -> bool:
        return self.access_path.base == ZERO_BASE

    def derive(self, ap: AccessPath, is_alias: bool = False) -> "TaintAbstraction":
        """A new fact for ``ap`` keeping this fact's source provenance."""
        return TaintAbstraction(
            access_path=ap,
            source_stmt=self.source_stmt,
            source_method=self.source_method,
            source_api=self.source_api,
            source_category=self.source_category,
            is_alias=is_alias,
        )

    @property
    def base(self) -> str:
        return self.access_path.base

    def __str__(self) -> str:
        if self.is_zero:
            return "ZERO"
        suffix = "(alias)" if self.is_alias else ""
        return f"{self.access_path}{suffix}"


ZERO = TaintAbstraction(access_path=AccessPath(ZERO_BASE, (), False))


# ---------------------------------------------------------------------------
# Source / sink management
# ---------------------------------------------------------------------------


class SourceSinkManager:
    """Decides which call sites are taint sources and which are sinks.

    Statement-level ``is_source``/``is_sink`` flags take priority; the
    program's ``source_sink_spec`` is consulted as a fallback so a program
    that only declares its APIs in the spec still analyses correctly.
    """

    def __init__(self, program: Program) -> None:
        spec = program.source_sink_spec or {}
        self.sources: dict[tuple[str, str], str] = {}
        self.sinks: dict[tuple[str, str], str] = {}
        for entry in spec.get("sources", []):
            self.sources[(entry["class_name"], entry["method_name"])] = entry.get(
                "category", "UNKNOWN"
            )
        for entry in spec.get("sinks", []):
            self.sinks[(entry["class_name"], entry["method_name"])] = entry.get(
                "category", "UNKNOWN"
            )

    def _key(self, unit: JimpleStmt) -> tuple[str, str] | None:
        if unit.callee is None:
            return None
        return (unit.callee.class_name, unit.callee.method_name)

    def is_source(self, unit: JimpleStmt) -> bool:
        if unit.is_source:
            return True
        key = self._key(unit)
        return key is not None and key in self.sources

    def is_sink(self, unit: JimpleStmt) -> bool:
        if unit.is_sink:
            return True
        key = self._key(unit)
        return key is not None and key in self.sinks

    def source_category(self, unit: JimpleStmt) -> str:
        if unit.raw.source_category:
            return unit.raw.source_category
        key = self._key(unit)
        return self.sources.get(key, "UNKNOWN") if key else "UNKNOWN"

    def sink_category(self, unit: JimpleStmt) -> str:
        if unit.raw.sink_category:
            return unit.raw.sink_category
        key = self._key(unit)
        return self.sinks.get(key, "UNKNOWN") if key else "UNKNOWN"

    def api_name(self, unit: JimpleStmt) -> str:
        return unit.callee.method_name if unit.callee else "<unknown>"


# ---------------------------------------------------------------------------
# Aliasing
# ---------------------------------------------------------------------------


class AliasManager:
    """Flow-insensitive may-alias sets over the locals of one method.

    Locals joined by a copy assignment (``r5 = r4``) may point at the same
    object, so a heap write through one of them must taint the same field
    of the others. This is the lightweight stand-in for FlowDroid's
    on-demand backwards alias search.
    """

    def __init__(self, body: JimpleBody) -> None:
        self.body = body
        self._parent: dict[str, str] = {}
        self._build()

    def _find(self, x: str) -> str:
        self._parent.setdefault(x, x)
        while self._parent[x] != x:
            self._parent[x] = self._parent[self._parent[x]]
            x = self._parent[x]
        return x

    def _union(self, a: str, b: str) -> None:
        ra, rb = self._find(a), self._find(b)
        if ra != rb:
            # Keep the lexicographically smaller root for determinism.
            if rb < ra:
                ra, rb = rb, ra
            self._parent[rb] = ra

    def _build(self) -> None:
        for local in self.body.locals:
            self._parent.setdefault(local.name, local.name)
        for unit in self.body:
            if unit.kind != "assign":
                continue
            raw = unit.raw
            if raw.lhs is None or len(raw.rhs_vars) != 1:
                continue
            src = raw.rhs_vars[0]
            if raw.rhs != src or not self.body.is_local(src):
                continue
            if self._is_reference(raw.lhs) and self._is_reference(src):
                self._union(raw.lhs, src)

    def _is_reference(self, name: str) -> bool:
        local = self.body.local_by_name(name)
        if local is None:
            return False
        return not _parse_type(local.type_name).is_primitive

    def aliases_of(self, name: str) -> list[str]:
        """All locals that may refer to the same object as ``name``."""
        if name not in self._parent:
            return [name]
        root = self._find(name)
        return sorted(v for v in self._parent if self._find(v) == root)

    def may_alias(self, a: str, b: str) -> bool:
        if a not in self._parent or b not in self._parent:
            return a == b
        return self._find(a) == self._find(b)


# ---------------------------------------------------------------------------
# Taint wrapper interface
# ---------------------------------------------------------------------------


class ITaintWrapper:
    """Interface for modelling calls whose body is not analysed.

    ``stubdroid_analysis`` supplies a summary-backed implementation; the
    default below is the conservative fallback FlowDroid uses when no
    summary is available.
    """

    def supports_callee(self, signature: MethodSignature) -> bool:
        raise NotImplementedError

    def get_taints_for_method(
        self, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody
    ) -> list[TaintAbstraction]:
        raise NotImplementedError


class DefaultTaintWrapper(ITaintWrapper):
    """Conservative model for unmodelled library calls.

    Taint flows from any tainted argument to the return value and to the
    receiver (a tainted value put into an object taints that object), and
    from a tainted receiver to the return value. This is what lets
    ``StringBuilder.append``/``toString`` chains carry taint without any
    library code being available.
    """

    def supports_callee(self, signature: MethodSignature) -> bool:
        return True

    def get_taints_for_method(
        self, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody
    ) -> list[TaintAbstraction]:
        out: list[TaintAbstraction] = []
        base = fact.base
        tainted_arg = any(base == a for a in unit.args if body.is_local(a))
        tainted_recv = unit.receiver is not None and base == unit.receiver

        if tainted_arg:
            if unit.lhs and body.is_local(unit.lhs):
                out.append(fact.derive(AccessPath.of(unit.lhs)))
            if unit.receiver and body.is_local(unit.receiver):
                out.append(fact.derive(AccessPath.of(unit.receiver)))
        if tainted_recv and unit.lhs and body.is_local(unit.lhs):
            out.append(fact.derive(AccessPath.of(unit.lhs)))
        return out


# ---------------------------------------------------------------------------
# Flow functions
# ---------------------------------------------------------------------------


class TaintFlowFunctions:
    """The four IFDS flow functions specialised for taint propagation."""

    def __init__(self, analysis: "FlowDroidAnalysis") -> None:
        self.analysis = analysis
        self.scene = analysis.scene
        self.ssm = analysis.source_sink_manager

    # -- normal ------------------------------------------------------------
    def normal(
        self, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody
    ) -> list[TaintAbstraction]:
        if fact.is_zero:
            return [fact]
        kind = unit.kind
        if kind == "assign":
            return self._assign(unit, fact, body)
        if kind == "new":
            return self._kill_if_defines(unit, fact)
        if kind == "field_store":
            return self._field_store(unit, fact, body)
        if kind == "field_load":
            return self._field_load(unit, fact, body)
        return [fact]

    def _kill_if_defines(self, unit: JimpleStmt, fact: TaintAbstraction) -> list[TaintAbstraction]:
        if unit.lhs is not None and fact.base == unit.lhs:
            return []
        return [fact]

    def _assign(
        self, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody
    ) -> list[TaintAbstraction]:
        raw = unit.raw
        lhs = raw.lhs
        out: list[TaintAbstraction] = []
        sources = [v for v in raw.rhs_vars if body.is_local(v)]
        if not sources and raw.rhs is not None and body.is_local(raw.rhs):
            sources = [raw.rhs]

        # The tainted value is read: the destination becomes tainted too.
        if lhs is not None and any(fact.base == s for s in sources):
            out.append(fact.derive(fact.access_path.rebase(lhs)))

        # The destination is overwritten: the old fact dies (strong update).
        if lhs is not None and fact.base == lhs and fact.base not in sources:
            return out
        out.append(fact)
        return out

    def _field_store(
        self, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody
    ) -> list[TaintAbstraction]:
        ref = unit.field_ref
        if ref is None:
            return [fact]
        raw = unit.raw
        out: list[TaintAbstraction] = [fact]
        sources = [v for v in raw.rhs_vars if body.is_local(v)]
        if not sources and raw.rhs is not None and body.is_local(raw.rhs):
            sources = [raw.rhs]

        if any(fact.base == s for s in sources):
            # base.f (and every may-alias of base) becomes tainted.
            aliases = self.analysis.alias_manager_for(body).aliases_of(ref.base)
            for alias in aliases:
                ap = fact.access_path.prepend_to(alias, ref.field_name)
                out.append(fact.derive(ap, is_alias=(alias != ref.base)))
        elif fact.base == ref.base and fact.access_path.first_field() == ref.field_name:
            # Overwritten with untainted data: strong update on the exact path.
            return []
        return out

    def _field_load(
        self, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody
    ) -> list[TaintAbstraction]:
        ref = unit.field_ref
        lhs = unit.lhs
        if ref is None or lhs is None:
            return [fact]
        out: list[TaintAbstraction] = []
        if fact.base == ref.base and fact.access_path.can_read_field(ref.field_name):
            tail = (
                fact.access_path.drop_first_field()
                if fact.access_path.fields
                else fact.access_path
            )
            out.append(fact.derive(tail.rebase(lhs)))
        if fact.base == lhs:
            return out  # overwritten
        out.append(fact)
        return out

    # -- call --------------------------------------------------------------
    def call(
        self,
        unit: JimpleStmt,
        fact: TaintAbstraction,
        caller_body: JimpleBody,
        callee: SootMethod,
    ) -> list[TaintAbstraction]:
        """Map a caller fact onto the callee's parameter/this locals."""
        callee_body = callee.body
        if callee_body is None:
            return []
        if fact.is_zero:
            return [fact]

        out: list[TaintAbstraction] = []
        for idx, arg in enumerate(unit.args):
            if not caller_body.is_local(arg) or fact.base != arg:
                continue
            if idx >= len(callee_body.param_locals):
                continue
            param = callee_body.param_locals[idx]
            out.append(fact.derive(fact.access_path.rebase(param)))

        if (
            unit.receiver is not None
            and fact.base == unit.receiver
            and callee_body.this_local
            and not callee.is_static
        ):
            out.append(fact.derive(fact.access_path.rebase(callee_body.this_local)))
        return out

    # -- return ------------------------------------------------------------
    def ret(
        self,
        exit_unit: JimpleStmt,
        fact: TaintAbstraction,
        call_unit: JimpleStmt,
        caller_body: JimpleBody,
        callee: SootMethod,
    ) -> list[TaintAbstraction]:
        """Map a callee exit fact back into the caller."""
        callee_body = callee.body
        if callee_body is None or fact.is_zero:
            return []
        out: list[TaintAbstraction] = []

        # Returned value flows into the call's result local.
        ret_var = exit_unit.rhs if exit_unit.kind == "return" else None
        if (
            ret_var is not None
            and callee_body.is_local(ret_var)
            and fact.base == ret_var
            and call_unit.lhs is not None
            and caller_body.is_local(call_unit.lhs)
        ):
            out.append(fact.derive(fact.access_path.rebase(call_unit.lhs)))

        # Heap state reachable through `this` is visible to the caller.
        if (
            callee_body.this_local
            and fact.base == callee_body.this_local
            and call_unit.receiver is not None
            and caller_body.is_local(call_unit.receiver)
            and fact.access_path.fields
        ):
            out.append(fact.derive(fact.access_path.rebase(call_unit.receiver)))

        # Heap state reachable through a parameter is visible to the caller.
        for idx, param in enumerate(callee_body.param_locals):
            if fact.base != param or not fact.access_path.fields:
                continue
            if idx >= len(call_unit.args):
                continue
            arg = call_unit.args[idx]
            if caller_body.is_local(arg):
                out.append(fact.derive(fact.access_path.rebase(arg)))
        return out

    # -- call-to-return ----------------------------------------------------
    def call_to_return(
        self, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody, has_callee: bool
    ) -> list[TaintAbstraction]:
        out: list[TaintAbstraction] = []

        # A source call turns the tautological fact into a fresh taint.
        if fact.is_zero:
            out.append(fact)
            if self.ssm.is_source(unit) and unit.lhs and body.is_local(unit.lhs):
                out.append(
                    TaintAbstraction(
                        access_path=AccessPath.of(unit.lhs),
                        source_stmt=unit.stmt_id,
                        source_method=body.signature.full_signature(),
                        source_api=self.ssm.api_name(unit),
                        source_category=self.ssm.source_category(unit),
                    )
                )
            return out

        if not has_callee:
            # No body to descend into: fall back to the taint wrapper.
            out.extend(self.analysis.taint_wrapper.get_taints_for_method(unit, fact, body))

        # The caller's own locals keep their taint across the call, unless
        # the call overwrites them with its result.
        if not (unit.lhs is not None and fact.base == unit.lhs):
            out.append(fact)
        return out


# ---------------------------------------------------------------------------
# Android lifecycle modelling
# ---------------------------------------------------------------------------


class LifecycleModel:
    """Synthesises a dummy main method per Android component.

    Android never calls lifecycle callbacks directly; the framework does.
    Analysing each callback in isolation would lose any taint parked in a
    field by an earlier callback, so we build an artificial method that
    allocates the component once and invokes its callbacks in the canonical
    order on that single object. Field taint then flows naturally from
    ``onCreate`` into ``onResume``.
    """

    ORDER: dict[str, list[str]] = {
        "activity": [
            "onCreate", "onStart", "onRestoreInstanceState", "onPostCreate",
            "onResume", "onPostResume", "onCreateOptionsMenu", "onOptionsItemSelected",
            "onPause", "onSaveInstanceState", "onStop", "onRestart", "onDestroy",
        ],
        "service": [
            "onCreate", "onStart", "onStartCommand", "onBind",
            "onRebind", "onUnbind", "onDestroy",
        ],
        "receiver": ["onReceive"],
        "provider": ["onCreate", "query", "insert", "update", "delete", "getType"],
        "fragment": [
            "onAttach", "onCreate", "onCreateView", "onStart", "onResume",
            "onPause", "onStop", "onDestroyView", "onDestroy", "onDetach",
        ],
    }

    #: Callbacks that are not part of any component's lifecycle but are still
    #: reachable from the framework (listeners registered in the manifest/UI).
    GENERIC_CALLBACK_PREFIXES = ("onClick", "onItemClick", "onTouch", "onKey", "onHandle")

    def __init__(self, scene: Scene) -> None:
        self.scene = scene
        self._next_id = SYNTHETIC_ID_BASE
        self.components_modelled = 0
        self.callbacks_modelled = 0

    def _fresh_id(self) -> int:
        self._next_id += 1
        return self._next_id

    def lifecycle_methods_of(self, class_name: str) -> list[SootMethod]:
        """Component callbacks in canonical lifecycle order."""
        cls = self.scene.get_class(class_name)
        if cls is None:
            return []
        order = self.ORDER.get(cls.component_type or "", [])
        by_name: dict[str, list[SootMethod]] = defaultdict(list)
        for m in cls.methods:
            if m.body is not None and not m.is_constructor:
                by_name[m.name].append(m)

        ordered: list[SootMethod] = []
        for name in order:
            for m in sorted(by_name.get(name, []), key=lambda x: x.full_signature()):
                ordered.append(m)
        # Entry points outside the canonical order (e.g. UI callbacks) run last.
        listed = {m.full_signature() for m in ordered}
        for name in sorted(by_name):
            if name in order:
                continue
            for m in by_name[name]:
                if m.full_signature() in listed:
                    continue
                if m.is_entry_point or name.startswith(self.GENERIC_CALLBACK_PREFIXES):
                    ordered.append(m)
        return ordered

    def build_dummy_main(self, cls_name: str) -> SootMethod | None:
        """Create ``<cls: void dummyMainOfComponent()>`` for a component."""
        callbacks = self.lifecycle_methods_of(cls_name)
        if not callbacks:
            return None

        component_local = "cmp0"
        locals_: list[Variable] = [Variable(component_local, _parse_type(cls_name))]
        statements: list[Statement] = [
            Statement(
                stmt_id=self._fresh_id(),
                kind="new",
                lhs=component_local,
                rhs=cls_name,
                metadata={"synthetic": True},
            )
        ]

        arg_counter = 0
        for cb in callbacks:
            args: list[str] = []
            for ptype in cb.signature.param_types:
                arg_name = f"arg{arg_counter}"
                arg_counter += 1
                locals_.append(Variable(arg_name, _parse_type(ptype)))
                statements.append(
                    Statement(
                        stmt_id=self._fresh_id(),
                        kind="new",
                        lhs=arg_name,
                        rhs=ptype,
                        metadata={"synthetic": True},
                    )
                )
                args.append(arg_name)
            statements.append(
                Statement(
                    stmt_id=self._fresh_id(),
                    kind="call",
                    callee=cb.signature,
                    receiver=None if cb.is_static else component_local,
                    args=args,
                    metadata={"synthetic": True, "lifecycle": cb.name},
                )
            )
            self.callbacks_modelled += 1
        statements.append(
            Statement(stmt_id=self._fresh_id(), kind="return", metadata={"synthetic": True})
        )

        sig = MethodSignature(cls_name, "dummyMainOfComponent", [], "void")
        body = MethodBody(locals=locals_, statements=statements, this_local=None, param_locals=[])
        jimple = JimpleBuilder().build(sig, body)

        decl = _synthetic_method_decl(sig)
        method = SootMethod(decl, self.scene.get_class(cls_name), jimple)
        method.is_static = True
        self.scene.methods[method.full_signature()] = method
        self.components_modelled += 1
        return method


def _synthetic_method_decl(sig: MethodSignature):
    from program_model import Method

    return Method(signature=sig, body=None, is_static=True, is_entry_point=True)


# ---------------------------------------------------------------------------
# IFDS solver
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class Leak:
    """A reported source-to-sink flow."""

    source_stmt: int
    sink_stmt: int
    source_method: str
    sink_method: str
    tainted_path: tuple[str, ...] = ()
    source_category: str = ""
    sink_category: str = ""

    def key(self) -> tuple[int, int, str, str]:
        """The identity used when comparing against ``expected_leaks``."""
        return (self.source_stmt, self.sink_stmt, self.source_method, self.sink_method)

    def to_dict(self) -> dict:
        return {
            "source_stmt": self.source_stmt,
            "sink_stmt": self.sink_stmt,
            "source_method": self.source_method,
            "sink_method": self.sink_method,
            "tainted_path": list(self.tainted_path),
        }

    def __str__(self) -> str:
        path = " -> ".join(self.tainted_path)
        return (
            f"{self.source_method}@{self.source_stmt} ==> "
            f"{self.sink_method}@{self.sink_stmt} [{path}]"
        )


class IFDSSolver:
    """The IFDS tabulation algorithm (Reps-Horwitz-Sagiv).

    Path edges are ``(method, entry_fact, stmt, fact)``. Procedure summaries
    (``end_summary``) plus the ``incoming`` map give full context sensitivity
    without re-analysing a callee per calling context.
    """

    def __init__(self, analysis: "FlowDroidAnalysis") -> None:
        self.analysis = analysis
        self.scene = analysis.scene
        self.flows = analysis.flow_functions
        self.ssm = analysis.source_sink_manager

        self.path_edges: set[tuple[str, TaintAbstraction, int, TaintAbstraction]] = set()
        self.worklist: deque[tuple[str, TaintAbstraction, int, TaintAbstraction]] = deque()
        self.end_summary: dict[tuple[str, TaintAbstraction], set[TaintAbstraction]] = defaultdict(set)
        self.incoming: dict[
            tuple[str, TaintAbstraction], set[tuple[str, TaintAbstraction, int, TaintAbstraction]]
        ] = defaultdict(set)
        #: One representative predecessor per fact, used to rebuild taint paths.
        self.predecessor: dict[tuple[str, int, TaintAbstraction], tuple[str, int, TaintAbstraction]] = {}
        self.leaks: dict[tuple[int, int, str, str], Leak] = {}
        self.propagations = 0

    # -- driver ------------------------------------------------------------
    def solve(self, entry_points: list[SootMethod]) -> list[Leak]:
        for method in entry_points:
            if method.body is None or not method.body.units:
                continue
            start = method.body.units[0].stmt_id
            self._propagate(method.full_signature(), ZERO, start, ZERO, None)

        while self.worklist:
            m, d1, n, d2 = self.worklist.popleft()
            self._process(m, d1, n, d2)

        return sorted(self.leaks.values(), key=lambda l: l.key())

    def _propagate(
        self,
        method: str,
        d1: TaintAbstraction,
        stmt: int,
        d2: TaintAbstraction,
        origin: tuple[str, int, TaintAbstraction] | None,
    ) -> None:
        edge = (method, d1, stmt, d2)
        if edge in self.path_edges:
            return
        self.path_edges.add(edge)
        self.propagations += 1
        key = (method, stmt, d2)
        if origin is not None and key not in self.predecessor and origin != key:
            self.predecessor[key] = origin
        self.worklist.append(edge)

    # -- per-unit processing -----------------------------------------------
    def _process(self, m: str, d1: TaintAbstraction, n: int, d2: TaintAbstraction) -> None:
        method = self.scene.get_method(m)
        if method is None or method.body is None:
            return
        body = method.body
        unit = body.unit_by_id(n)
        if unit is None:
            return
        origin = (m, n, d2)

        if unit.is_invoke():
            self._process_call(m, d1, unit, d2, method, body, origin)
        elif not body.graph.successors(n):
            self._process_exit(m, d1, unit, d2)
        else:
            for out_fact in self.flows.normal(unit, d2, body):
                for succ in body.graph.successors(n):
                    self._propagate(m, d1, succ, out_fact, origin)

    def _process_call(
        self,
        m: str,
        d1: TaintAbstraction,
        unit: JimpleStmt,
        d2: TaintAbstraction,
        method: SootMethod,
        body: JimpleBody,
        origin: tuple[str, int, TaintAbstraction],
    ) -> None:
        n = unit.stmt_id
        self._check_sink(m, unit, d2, body)

        callees = self.analysis.callees_of(m, unit)
        for callee in callees:
            callee_body = callee.body
            if callee_body is None or not callee_body.units:
                continue
            entry = callee_body.units[0].stmt_id
            csig = callee.full_signature()
            for d3 in self.flows.call(unit, d2, body, callee):
                self._propagate(csig, d3, entry, d3, origin)
                self.incoming[(csig, d3)].add((m, d1, n, d2))
                for d4 in sorted(self.end_summary[(csig, d3)], key=str):
                    self._apply_summary(m, d1, unit, d2, body, callee, d4)

        for d3 in self.flows.call_to_return(unit, d2, body, has_callee=bool(callees)):
            for succ in body.graph.successors(n):
                self._propagate(m, d1, succ, d3, origin)

        if not body.graph.successors(n):
            # A call in tail position is also an exit of its method.
            self._process_exit(m, d1, unit, d2)

    def _apply_summary(
        self,
        m: str,
        d1: TaintAbstraction,
        call_unit: JimpleStmt,
        d2: TaintAbstraction,
        body: JimpleBody,
        callee: SootMethod,
        exit_fact: TaintAbstraction,
    ) -> None:
        assert callee.body is not None
        for exit_unit in self._exit_units(callee):
            for d5 in self.flows.ret(exit_unit, exit_fact, call_unit, body, callee):
                for succ in body.graph.successors(call_unit.stmt_id):
                    self._propagate(
                        m, d1, succ, d5, (callee.full_signature(), exit_unit.stmt_id, exit_fact)
                    )

    def _exit_units(self, method: SootMethod) -> list[JimpleStmt]:
        assert method.body is not None
        return [u for u in method.body if not method.body.graph.successors(u.stmt_id)]

    def _process_exit(
        self, m: str, d1: TaintAbstraction, unit: JimpleStmt, d2: TaintAbstraction
    ) -> None:
        method = self.scene.get_method(m)
        if method is None:
            return
        self.end_summary[(m, d1)].add(d2)
        for cm, cd1, cn, cd2 in sorted(self.incoming[(m, d1)], key=lambda x: (x[0], x[2], str(x[3]))):
            caller = self.scene.get_method(cm)
            if caller is None or caller.body is None:
                continue
            call_unit = caller.body.unit_by_id(cn)
            if call_unit is None:
                continue
            for d5 in self.flows.ret(unit, d2, call_unit, caller.body, method):
                for succ in caller.body.graph.successors(cn):
                    self._propagate(cm, cd1, succ, d5, (m, unit.stmt_id, d2))

    # -- sinks -------------------------------------------------------------
    def _check_sink(
        self, m: str, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody
    ) -> None:
        if fact.is_zero or not self.ssm.is_sink(unit):
            return
        flowing = [a for a in unit.args if body.is_local(a) and a == fact.base]
        if unit.receiver is not None and unit.receiver == fact.base:
            flowing.append(unit.receiver)
        if not flowing:
            return
        leak = Leak(
            source_stmt=fact.source_stmt,
            sink_stmt=unit.stmt_id,
            source_method=fact.source_api,
            sink_method=self.ssm.api_name(unit),
            tainted_path=self._reconstruct_path(m, unit.stmt_id, fact),
            source_category=fact.source_category,
            sink_category=self.ssm.sink_category(unit),
        )
        self.leaks.setdefault(leak.key(), leak)

    def _reconstruct_path(
        self, method: str, stmt: int, fact: TaintAbstraction
    ) -> tuple[str, ...]:
        """Walk the predecessor chain back to the source, newest last."""
        chain: list[tuple[str, TaintAbstraction]] = []
        cur: tuple[str, int, TaintAbstraction] | None = (method, stmt, fact)
        seen: set[tuple[str, int, TaintAbstraction]] = set()
        while cur is not None and cur not in seen:
            seen.add(cur)
            chain.append((cur[0], cur[2]))
            cur = self.predecessor.get(cur)

        chain.reverse()
        source_method = fact.source_method
        rendered: list[str] = []
        for owner, f in chain:
            if f.is_zero:
                continue
            label = str(f.access_path)
            if f.is_alias:
                label += "(alias)"
            elif owner != source_method:
                short = self.scene.get_method(owner)
                if short is not None:
                    label += f"({short.signature.method_name})"
            if not rendered or rendered[-1] != label:
                rendered.append(label)
        return tuple(rendered)


# ---------------------------------------------------------------------------
# Analysis driver
# ---------------------------------------------------------------------------


@dataclass
class FlowDroidResult:
    program_name: str
    leaks: list[Leak]
    expected: list[dict]
    true_positives: int
    false_positives: int
    false_negatives: int
    propagations: int
    path_edges: int
    entry_points: int
    components_modelled: int
    callbacks_modelled: int
    elapsed_ms: float
    exact_paths: int = 0

    @property
    def matches_expected(self) -> bool:
        return self.false_positives == 0 and self.false_negatives == 0


class FlowDroidAnalysis:
    """FlowDroid-style taint analysis over one :class:`Program`."""

    def __init__(
        self,
        program: Program,
        taint_wrapper: ITaintWrapper | None = None,
        scene: Scene | None = None,
    ) -> None:
        self.program = program
        self.scene = scene if scene is not None else reset_scene().load_program(program)
        self.source_sink_manager = SourceSinkManager(program)
        self.taint_wrapper: ITaintWrapper = taint_wrapper or DefaultTaintWrapper()
        self.flow_functions = TaintFlowFunctions(self)
        self.call_graph: CallGraph = CHACallGraphBuilder(self.scene).build()
        self.lifecycle = LifecycleModel(self.scene)
        self._alias_cache: dict[str, AliasManager] = {}
        self.solver: IFDSSolver | None = None

    # -- helpers -----------------------------------------------------------
    def alias_manager_for(self, body: JimpleBody) -> AliasManager:
        key = body.signature.full_signature()
        cached = self._alias_cache.get(key)
        if cached is None or cached.body is not body:
            cached = AliasManager(body)
            self._alias_cache[key] = cached
        return cached

    def callees_of(self, method: str, unit: JimpleStmt) -> list[SootMethod]:
        """Concrete call targets with an analysable body at this call site."""
        if unit.callee is None:
            return []
        if self.taint_wrapper.supports_callee(unit.callee) and not isinstance(
            self.taint_wrapper, DefaultTaintWrapper
        ):
            # A summary exists: model the call instead of descending into it.
            return []
        targets: list[SootMethod] = []
        for edge in self.call_graph.edges_out_of_site(method, unit.stmt_id):
            callee = self.scene.get_method(edge.tgt_method)
            if callee is not None and callee.body is not None:
                targets.append(callee)
        if not targets:
            direct = self.scene.get_method(unit.callee)
            if direct is not None and direct.body is not None:
                targets.append(direct)
        return targets

    def entry_points(self) -> list[SootMethod]:
        """Dummy mains for components, plus any standalone entry point."""
        entries: list[SootMethod] = []
        covered: set[str] = set()
        for cls in self.scene.android_components():
            dummy = self.lifecycle.build_dummy_main(cls.name)
            if dummy is None:
                continue
            entries.append(dummy)
            for cb in self.lifecycle.lifecycle_methods_of(cls.name):
                covered.add(cb.full_signature())
        for method in self.scene.get_entry_points():
            if method.full_signature() in covered or method.body is None:
                continue
            entries.append(method)
        return entries

    # -- run ---------------------------------------------------------------
    def run(self) -> FlowDroidResult:
        with Timer() as t:
            entries = self.entry_points()
            self.solver = IFDSSolver(self)
            leaks = self.solver.solve(entries)

        expected = self.program.expected_leaks or []
        expected_keys = {
            (
                e.get("source_stmt"),
                e.get("sink_stmt"),
                e.get("source_method"),
                e.get("sink_method"),
            )
            for e in expected
        }
        found_keys = {l.key() for l in leaks}
        tp = len(found_keys & expected_keys)
        fp = len(found_keys - expected_keys)
        fn = len(expected_keys - found_keys)

        exact = 0
        by_key = {l.key(): l for l in leaks}
        for e in expected:
            key = (
                e.get("source_stmt"),
                e.get("sink_stmt"),
                e.get("source_method"),
                e.get("sink_method"),
            )
            leak = by_key.get(key)
            if leak is not None and list(leak.tainted_path) == list(e.get("tainted_path", [])):
                exact += 1

        return FlowDroidResult(
            program_name=self.program.name,
            leaks=leaks,
            expected=expected,
            true_positives=tp,
            false_positives=fp,
            false_negatives=fn,
            propagations=self.solver.propagations,
            path_edges=len(self.solver.path_edges),
            entry_points=len(entries),
            components_modelled=self.lifecycle.components_modelled,
            callbacks_modelled=self.lifecycle.callbacks_modelled,
            elapsed_ms=t.elapsed_ms,
            exact_paths=exact,
        )


def analyze_program(program: Program, taint_wrapper: ITaintWrapper | None = None) -> FlowDroidResult:
    return FlowDroidAnalysis(program, taint_wrapper=taint_wrapper).run()


# ---------------------------------------------------------------------------
# Driver
# ---------------------------------------------------------------------------


def _benchmark_dir() -> str:
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), "benchmarks")


def format_metrics(tp: int, fp: int, fn: int) -> tuple[float, float, float]:
    precision = tp / (tp + fp) if (tp + fp) else 1.0
    recall = tp / (tp + fn) if (tp + fn) else 1.0
    f1 = 2 * precision * recall / (precision + recall) if (precision + recall) else 0.0
    return precision, recall, f1


def main(argv: list[str] | None = None) -> int:
    argv = list(sys.argv[1:] if argv is None else argv)
    directory = argv[0] if argv else _benchmark_dir()
    programs = load_all_benchmarks(directory)

    print("=== FlowDroid Analysis (IFDS taint tracking) ===")
    print("ANALYSIS_LAYER: flowdroid")
    print(f"PROGRAMS_ANALYZED: {len(programs)}")

    results: list[FlowDroidResult] = []
    for program in programs:
        res = analyze_program(program)
        results.append(res)
        print(f"--- {res.program_name} ---")
        print(f"{res.program_name}_LEAKS_FOUND: {len(res.leaks)}")
        print(f"{res.program_name}_LEAKS_EXPECTED: {len(res.expected)}")
        print(f"{res.program_name}_TRUE_POSITIVES: {res.true_positives}")
        print(f"{res.program_name}_FALSE_POSITIVES: {res.false_positives}")
        print(f"{res.program_name}_FALSE_NEGATIVES: {res.false_negatives}")
        print(f"{res.program_name}_ENTRY_POINTS: {res.entry_points}")
        print(f"{res.program_name}_LIFECYCLE_CALLBACKS: {res.callbacks_modelled}")
        print(f"{res.program_name}_IFDS_PROPAGATIONS: {res.propagations}")
        print(f"{res.program_name}_IFDS_PATH_EDGES: {res.path_edges}")
        print(f"{res.program_name}_MATCHES_EXPECTED: {res.matches_expected}")
        for i, leak in enumerate(res.leaks):
            print(f"{res.program_name}_LEAK_{i}: {leak}")

    tp = sum(r.true_positives for r in results)
    fp = sum(r.false_positives for r in results)
    fn = sum(r.false_negatives for r in results)
    precision, recall, f1 = format_metrics(tp, fp, fn)
    passed = sum(1 for r in results if r.matches_expected)

    print("--- totals ---")
    print(f"TOTAL_LEAKS_FOUND: {sum(len(r.leaks) for r in results)}")
    print(f"TOTAL_LEAKS_EXPECTED: {sum(len(r.expected) for r in results)}")
    print(f"TOTAL_TRUE_POSITIVES: {tp}")
    print(f"TOTAL_FALSE_POSITIVES: {fp}")
    print(f"TOTAL_FALSE_NEGATIVES: {fn}")
    print(f"PRECISION: {precision:.4f}")
    print(f"RECALL: {recall:.4f}")
    print(f"F1_SCORE: {f1:.4f}")
    print(f"BENCHMARKS_PASSED: {passed}")
    print(f"BENCHMARKS_TOTAL: {len(results)}")
    print(f"EXACT_PATH_MATCHES: {sum(r.exact_paths for r in results)}")
    print(f"TOTAL_COMPONENTS_MODELLED: {sum(r.components_modelled for r in results)}")
    print(f"TOTAL_LIFECYCLE_CALLBACKS: {sum(r.callbacks_modelled for r in results)}")
    print(f"TOTAL_IFDS_PROPAGATIONS: {sum(r.propagations for r in results)}")
    print(f"TOTAL_IFDS_PATH_EDGES: {sum(r.path_edges for r in results)}")
    print(f"TOTAL_ANALYSIS_MS: {sum(r.elapsed_ms for r in results):.3f}")
    print(f"FLOWDROID_ANALYSIS_STATUS: {'OK' if passed == len(results) else 'MISMATCH'}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

toolUseResult.content:
"""
FlowDroid-style IFDS taint analysis.

Builds on the Jimple IR, scene registry and CHA call graph provided by
``soot_analysis`` and adds a context-sensitive, flow-sensitive,
field-sensitive taint analysis:

  * ``AccessPath``        -- base local plus a k-limited field chain
  * ``TaintAbstraction``  -- an IFDS data-flow fact (an access path plus the
                             source it originated from)
  * ``SourceSinkManager`` -- resolves sources/sinks from the program spec
  * ``AliasManager``      -- may-alias sets used to keep heap taint sound
  * ``TaintFlowFunctions``-- normal / call / return / call-to-return flows
  * ``IFDSSolver``        -- the IFDS tabulation algorithm with summaries
  * ``LifecycleModel``    -- synthesises an Android dummy-main per component
                             so taint survives across lifecycle callbacks
  * ``FlowDroidAnalysis`` -- ties it together and reports :class:`Leak` s

Run standalone with ``python3 flowdroid_analysis.py``.
"""

from __future__ import annotations

import os
import sys
from collections import defaultdict, deque
from dataclasses import dataclass, field
from typing import Iterable

from program_model import (
    MethodBody,
    MethodSignature,
    Program,
    Statement,
    Variable,
    _parse_type,
    load_all_benchmarks,
)
from soot_analysis import (
    CHACallGraphBuilder,
    CallGraph,
    JimpleBody,
    JimpleBuilder,
    JimpleStmt,
    Scene,
    SootMethod,
    is_constant_token,
    reset_scene,
)
from utils import Timer

#: Maximum number of fields tracked on an access path (FlowDroid's -al/k).
ACCESS_PATH_LENGTH = 5

#: Base name of the IFDS tautological (zero) fact.
ZERO_BASE = "<<zero>>"

#: Statement ids for synthesised dummy-main units start here so they can
#: never collide with ids coming from a benchmark body.
SYNTHETIC_ID_BASE = 100000


# ---------------------------------------------------------------------------
# Access paths
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class AccessPath:
    """A tainted memory location: a base local plus a field chain.

    ``taint_sub_fields`` marks the ``.*`` case -- the whole object is
    tainted, so reading any field of it yields tainted data.
    """

    base: str
    fields: tuple[str, ...] = ()
    taint_sub_fields: bool = True

    # -- construction ------------------------------------------------------
    @staticmethod
    def of(base: str, fields: Iterable[str] = (), taint_sub_fields: bool = True) -> "AccessPath":
        fs = tuple(fields)
        if len(fs) > ACCESS_PATH_LENGTH:
            # k-limiting: truncate and over-approximate the rest.
            return AccessPath(base, fs[:ACCESS_PATH_LENGTH], True)
        return AccessPath(base, fs, taint_sub_fields)

    def with_field(self, field_name: str) -> "AccessPath":
        return AccessPath.of(self.base, self.fields + (field_name,), self.taint_sub_fields)

    def drop_first_field(self) -> "AccessPath":
        return AccessPath.of(self.base, self.fields[1:], self.taint_sub_fields)

    def rebase(self, new_base: str) -> "AccessPath":
        return AccessPath.of(new_base, self.fields, self.taint_sub_fields)

    def prepend_to(self, base: str, field_name: str) -> "AccessPath":
        """``x`` tainted, storing into ``base.f`` yields ``base.f.<x fields>``."""
        return AccessPath.of(base, (field_name,) + self.fields, self.taint_sub_fields)

    # -- queries -----------------------------------------------------------
    @property
    def is_local_only(self) -> bool:
        return not self.fields

    def first_field(self) -> str | None:
        return self.fields[0] if self.fields else None

    def can_read_field(self, field_name: str) -> bool:
        """Whether loading ``field_name`` off this path yields tainted data."""
        if self.fields:
            return self.fields[0] == field_name
        # Whole object tainted: any field read is tainted only under .* semantics.
        return self.taint_sub_fields

    def starts_with(self, other: "AccessPath") -> bool:
        if self.base != other.base or len(self.fields) < len(other.fields):
            return False
        return self.fields[: len(other.fields)] == other.fields

    def __str__(self) -> str:
        return ".".join((self.base,) + self.fields)


# ---------------------------------------------------------------------------
# Taint facts
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class TaintAbstraction:
    """An IFDS fact: a tainted access path plus its provenance."""

    access_path: AccessPath
    source_stmt: int = -1
    source_method: str = ""
    source_api: str = ""
    source_category: str = ""
    is_alias: bool = False

    @staticmethod
    def zero() -> "TaintAbstraction":
        return ZERO

    @property
    def is_zero(self) -> bool:
        return self.access_path.base == ZERO_BASE

    def derive(self, ap: AccessPath, is_alias: bool = False) -> "TaintAbstraction":
        """A new fact for ``ap`` keeping this fact's source provenance."""
        return TaintAbstraction(
            access_path=ap,
            source_stmt=self.source_stmt,
            source_method=self.source_method,
            source_api=self.source_api,
            source_category=self.source_category,
            is_alias=is_alias,
        )

    @property
    def base(self) -> str:
        return self.access_path.base

    def __str__(self) -> str:
        if self.is_zero:
            return "ZERO"
        suffix = "(alias)" if self.is_alias else ""
        return f"{self.access_path}{suffix}"


ZERO = TaintAbstraction(access_path=AccessPath(ZERO_BASE, (), False))


# ---------------------------------------------------------------------------
# Source / sink management
# ---------------------------------------------------------------------------


class SourceSinkManager:
    """Decides which call sites are taint sources and which are sinks.

    Statement-level ``is_source``/``is_sink`` flags take priority; the
    program's ``source_sink_spec`` is consulted as a fallback so a program
    that only declares its APIs in the spec still analyses correctly.
    """

    def __init__(self, program: Program) -> None:
        spec = program.source_sink_spec or {}
        self.sources: dict[tuple[str, str], str] = {}
        self.sinks: dict[tuple[str, str], str] = {}
        for entry in spec.get("sources", []):
            self.sources[(entry["class_name"], entry["method_name"])] = entry.get(
                "category", "UNKNOWN"
            )
        for entry in spec.get("sinks", []):
            self.sinks[(entry["class_name"], entry["method_name"])] = entry.get(
                "category", "UNKNOWN"
            )

    def _key(self, unit: JimpleStmt) -> tuple[str, str] | None:
        if unit.callee is None:
            return None
        return (unit.callee.class_name, unit.callee.method_name)

    def is_source(self, unit: JimpleStmt) -> bool:
        if unit.is_source:
            return True
        key = self._key(unit)
        return key is not None and key in self.sources

    def is_sink(self, unit: JimpleStmt) -> bool:
        if unit.is_sink:
            return True
        key = self._key(unit)
        return key is not None and key in self.sinks

    def source_category(self, unit: JimpleStmt) -> str:
        if unit.raw.source_category:
            return unit.raw.source_category
        key = self._key(unit)
        return self.sources.get(key, "UNKNOWN") if key else "UNKNOWN"

    def sink_category(self, unit: JimpleStmt) -> str:
        if unit.raw.sink_category:
            return unit.raw.sink_category
        key = self._key(unit)
        return self.sinks.get(key, "UNKNOWN") if key else "UNKNOWN"

    def api_name(self, unit: JimpleStmt) -> str:
        return unit.callee.method_name if unit.callee else "<unknown>"


# ---------------------------------------------------------------------------
# Aliasing
# ---------------------------------------------------------------------------


class AliasManager:
    """Flow-insensitive may-alias sets over the locals of one method.

    Locals joined by a copy assignment (``r5 = r4``) may point at the same
    object, so a heap write through one of them must taint the same field
    of the others. This is the lightweight stand-in for FlowDroid's
    on-demand backwards alias search.
    """

    def __init__(self, body: JimpleBody) -> None:
        self.body = body
        self._parent: dict[str, str] = {}
        self._build()

    def _find(self, x: str) -> str:
        self._parent.setdefault(x, x)
        while self._parent[x] != x:
            self._parent[x] = self._parent[self._parent[x]]
            x = self._parent[x]
        return x

    def _union(self, a: str, b: str) -> None:
        ra, rb = self._find(a), self._find(b)
        if ra != rb:
            # Keep the lexicographically smaller root for determinism.
            if rb < ra:
                ra, rb = rb, ra
            self._parent[rb] = ra

    def _build(self) -> None:
        for local in self.body.locals:
            self._parent.setdefault(local.name, local.name)
        for unit in self.body:
            if unit.kind != "assign":
                continue
            raw = unit.raw
            if raw.lhs is None or len(raw.rhs_vars) != 1:
                continue
            src = raw.rhs_vars[0]
            if raw.rhs != src or not self.body.is_local(src):
                continue
            if self._is_reference(raw.lhs) and self._is_reference(src):
                self._union(raw.lhs, src)

    def _is_reference(self, name: str) -> bool:
        local = self.body.local_by_name(name)
        if local is None:
            return False
        return not _parse_type(local.type_name).is_primitive

    def aliases_of(self, name: str) -> list[str]:
        """All locals that may refer to the same object as ``name``."""
        if name not in self._parent:
            return [name]
        root = self._find(name)
        return sorted(v for v in self._parent if self._find(v) == root)

    def may_alias(self, a: str, b: str) -> bool:
        if a not in self._parent or b not in self._parent:
            return a == b
        return self._find(a) == self._find(b)


# ---------------------------------------------------------------------------
# Taint wrapper interface
# ---------------------------------------------------------------------------


class ITaintWrapper:
    """Interface for modelling calls whose body is not analysed.

    ``stubdroid_analysis`` supplies a summary-backed implementation; the
    default below is the conservative fallback FlowDroid uses when no
    summary is available.
    """

    def supports_callee(self, signature: MethodSignature) -> bool:
        raise NotImplementedError

    def get_taints_for_method(
        self, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody
    ) -> list[TaintAbstraction]:
        raise NotImplementedError


class DefaultTaintWrapper(ITaintWrapper):
    """Conservative model for unmodelled library calls.

    Taint flows from any tainted argument to the return value and to the
    receiver (a tainted value put into an object taints that object), and
    from a tainted receiver to the return value. This is what lets
    ``StringBuilder.append``/``toString`` chains carry taint without any
    library code being available.
    """

    def supports_callee(self, signature: MethodSignature) -> bool:
        return True

    def get_taints_for_method(
        self, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody
    ) -> list[TaintAbstraction]:
        out: list[TaintAbstraction] = []
        base = fact.base
        tainted_arg = any(base == a for a in unit.args if body.is_local(a))
        tainted_recv = unit.receiver is not None and base == unit.receiver

        if tainted_arg:
            if unit.lhs and body.is_local(unit.lhs):
                out.append(fact.derive(AccessPath.of(unit.lhs)))
            if unit.receiver and body.is_local(unit.receiver):
                out.append(fact.derive(AccessPath.of(unit.receiver)))
        if tainted_recv and unit.lhs and body.is_local(unit.lhs):
            out.append(fact.derive(AccessPath.of(unit.lhs)))
        return out


# ---------------------------------------------------------------------------
# Flow functions
# ---------------------------------------------------------------------------


class TaintFlowFunctions:
    """The four IFDS flow functions specialised for taint propagation."""

    def __init__(self, analysis: "FlowDroidAnalysis") -> None:
        self.analysis = analysis
        self.scene = analysis.scene
        self.ssm = analysis.source_sink_manager

    # -- normal ------------------------------------------------------------
    def normal(
        self, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody
    ) -> list[TaintAbstraction]:
        if fact.is_zero:
            return [fact]
        kind = unit.kind
        if kind == "assign":
            return self._assign(unit, fact, body)
        if kind == "new":
            return self._kill_if_defines(unit, fact)
        if kind == "field_store":
            return self._field_store(unit, fact, body)
        if kind == "field_load":
            return self._field_load(unit, fact, body)
        return [fact]

    def _kill_if_defines(self, unit: JimpleStmt, fact: TaintAbstraction) -> list[TaintAbstraction]:
        if unit.lhs is not None and fact.base == unit.lhs:
            return []
        return [fact]

    def _assign(
        self, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody
    ) -> list[TaintAbstraction]:
        raw = unit.raw
        lhs = raw.lhs
        out: list[TaintAbstraction] = []
        sources = [v for v in raw.rhs_vars if body.is_local(v)]
        if not sources and raw.rhs is not None and body.is_local(raw.rhs):
            sources = [raw.rhs]

        # The tainted value is read: the destination becomes tainted too.
        if lhs is not None and any(fact.base == s for s in sources):
            out.append(fact.derive(fact.access_path.rebase(lhs)))

        # The destination is overwritten: the old fact dies (strong update).
        if lhs is not None and fact.base == lhs and fact.base not in sources:
            return out
        out.append(fact)
        return out

    def _field_store(
        self, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody
    ) -> list[TaintAbstraction]:
        ref = unit.field_ref
        if ref is None:
            return [fact]
        raw = unit.raw
        out: list[TaintAbstraction] = [fact]
        sources = [v for v in raw.rhs_vars if body.is_local(v)]
        if not sources and raw.rhs is not None and body.is_local(raw.rhs):
            sources = [raw.rhs]

        if any(fact.base == s for s in sources):
            # base.f (and every may-alias of base) becomes tainted.
            aliases = self.analysis.alias_manager_for(body).aliases_of(ref.base)
            for alias in aliases:
                ap = fact.access_path.prepend_to(alias, ref.field_name)
                out.append(fact.derive(ap, is_alias=(alias != ref.base)))
        elif fact.base == ref.base and fact.access_path.first_field() == ref.field_name:
            # Overwritten with untainted data: strong update on the exact path.
            return []
        return out

    def _field_load(
        self, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody
    ) -> list[TaintAbstraction]:
        ref = unit.field_ref
        lhs = unit.lhs
        if ref is None or lhs is None:
            return [fact]
        out: list[TaintAbstraction] = []
        if fact.base == ref.base and fact.access_path.can_read_field(ref.field_name):
            tail = (
                fact.access_path.drop_first_field()
                if fact.access_path.fields
                else fact.access_path
            )
            out.append(fact.derive(tail.rebase(lhs)))
        if fact.base == lhs:
            return out  # overwritten
        out.append(fact)
        return out

    # -- call --------------------------------------------------------------
    def call(
        self,
        unit: JimpleStmt,
        fact: TaintAbstraction,
        caller_body: JimpleBody,
        callee: SootMethod,
    ) -> list[TaintAbstraction]:
        """Map a caller fact onto the callee's parameter/this locals."""
        callee_body = callee.body
        if callee_body is None:
            return []
        if fact.is_zero:
            return [fact]

        out: list[TaintAbstraction] = []
        for idx, arg in enumerate(unit.args):
            if not caller_body.is_local(arg) or fact.base != arg:
                continue
            if idx >= len(callee_body.param_locals):
                continue
            param = callee_body.param_locals[idx]
            out.append(fact.derive(fact.access_path.rebase(param)))

        if (
            unit.receiver is not None
            and fact.base == unit.receiver
            and callee_body.this_local
            and not callee.is_static
        ):
            out.append(fact.derive(fact.access_path.rebase(callee_body.this_local)))
        return out

    # -- return ------------------------------------------------------------
    def ret(
        self,
        exit_unit: JimpleStmt,
        fact: TaintAbstraction,
        call_unit: JimpleStmt,
        caller_body: JimpleBody,
        callee: SootMethod,
    ) -> list[TaintAbstraction]:
        """Map a callee exit fact back into the caller."""
        callee_body = callee.body
        if callee_body is None or fact.is_zero:
            return []
        out: list[TaintAbstraction] = []

        # Returned value flows into the call's result local.
        ret_var = exit_unit.rhs if exit_unit.kind == "return" else None
        if (
            ret_var is not None
            and callee_body.is_local(ret_var)
            and fact.base == ret_var
            and call_unit.lhs is not None
            and caller_body.is_local(call_unit.lhs)
        ):
            out.append(fact.derive(fact.access_path.rebase(call_unit.lhs)))

        # Heap state reachable through `this` is visible to the caller.
        if (
            callee_body.this_local
            and fact.base == callee_body.this_local
            and call_unit.receiver is not None
            and caller_body.is_local(call_unit.receiver)
            and fact.access_path.fields
        ):
            out.append(fact.derive(fact.access_path.rebase(call_unit.receiver)))

        # Heap state reachable through a parameter is visible to the caller.
        for idx, param in enumerate(callee_body.param_locals):
            if fact.base != param or not fact.access_path.fields:
                continue
            if idx >= len(call_unit.args):
                continue
            arg = call_unit.args[idx]
            if caller_body.is_local(arg):
                out.append(fact.derive(fact.access_path.rebase(arg)))
        return out

    # -- call-to-return ----------------------------------------------------
    def call_to_return(
        self, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody, has_callee: bool
    ) -> list[TaintAbstraction]:
        out: list[TaintAbstraction] = []

        # A source call turns the tautological fact into a fresh taint.
        if fact.is_zero:
            out.append(fact)
            if self.ssm.is_source(unit) and unit.lhs and body.is_local(unit.lhs):
                out.append(
                    TaintAbstraction(
                        access_path=AccessPath.of(unit.lhs),
                        source_stmt=unit.stmt_id,
                        source_method=body.signature.full_signature(),
                        source_api=self.ssm.api_name(unit),
                        source_category=self.ssm.source_category(unit),
                    )
                )
            return out

        if not has_callee:
            # No body to descend into: fall back to the taint wrapper.
            out.extend(self.analysis.taint_wrapper.get_taints_for_method(unit, fact, body))

        # The caller's own locals keep their taint across the call, unless
        # the call overwrites them with its result.
        if not (unit.lhs is not None and fact.base == unit.lhs):
            out.append(fact)
        return out


# ---------------------------------------------------------------------------
# Android lifecycle modelling
# ---------------------------------------------------------------------------


class LifecycleModel:
    """Synthesises a dummy main method per Android component.

    Android never calls lifecycle callbacks directly; the framework does.
    Analysing each callback in isolation would lose any taint parked in a
    field by an earlier callback, so we build an artificial method that
    allocates the component once and invokes its callbacks in the canonical
    order on that single object. Field taint then flows naturally from
    ``onCreate`` into ``onResume``.
    """

    ORDER: dict[str, list[str]] = {
        "activity": [
            "onCreate", "onStart", "onRestoreInstanceState", "onPostCreate",
            "onResume", "onPostResume", "onCreateOptionsMenu", "onOptionsItemSelected",
            "onPause", "onSaveInstanceState", "onStop", "onRestart", "onDestroy",
        ],
        "service": [
            "onCreate", "onStart", "onStartCommand", "onBind",
            "onRebind", "onUnbind", "onDestroy",
        ],
        "receiver": ["onReceive"],
        "provider": ["onCreate", "query", "insert", "update", "delete", "getType"],
        "fragment": [
            "onAttach", "onCreate", "onCreateView", "onStart", "onResume",
            "onPause", "onStop", "onDestroyView", "onDestroy", "onDetach",
        ],
    }

    #: Callbacks that are not part of any component's lifecycle but are still
    #: reachable from the framework (listeners registered in the manifest/UI).
    GENERIC_CALLBACK_PREFIXES = ("onClick", "onItemClick", "onTouch", "onKey", "onHandle")

    def __init__(self, scene: Scene) -> None:
        self.scene = scene
        self._next_id = SYNTHETIC_ID_BASE
        self.components_modelled = 0
        self.callbacks_modelled = 0

    def _fresh_id(self) -> int:
        self._next_id += 1
        return self._next_id

    def lifecycle_methods_of(self, class_name: str) -> list[SootMethod]:
        """Component callbacks in canonical lifecycle order."""
        cls = self.scene.get_class(class_name)
        if cls is None:
            return []
        order = self.ORDER.get(cls.component_type or "", [])
        by_name: dict[str, list[SootMethod]] = defaultdict(list)
        for m in cls.methods:
            if m.body is not None and not m.is_constructor:
                by_name[m.name].append(m)

        ordered: list[SootMethod] = []
        for name in order:
            for m in sorted(by_name.get(name, []), key=lambda x: x.full_signature()):
                ordered.append(m)
        # Entry points outside the canonical order (e.g. UI callbacks) run last.
        listed = {m.full_signature() for m in ordered}
        for name in sorted(by_name):
            if name in order:
                continue
            for m in by_name[name]:
                if m.full_signature() in listed:
                    continue
                if m.is_entry_point or name.startswith(self.GENERIC_CALLBACK_PREFIXES):
                    ordered.append(m)
        return ordered

    def build_dummy_main(self, cls_name: str) -> SootMethod | None:
        """Create ``<cls: void dummyMainOfComponent()>`` for a component."""
        callbacks = self.lifecycle_methods_of(cls_name)
        if not callbacks:
            return None

        component_local = "cmp0"
        locals_: list[Variable] = [Variable(component_local, _parse_type(cls_name))]
        statements: list[Statement] = [
            Statement(
                stmt_id=self._fresh_id(),
                kind="new",
                lhs=component_local,
                rhs=cls_name,
                metadata={"synthetic": True},
            )
        ]

        arg_counter = 0
        for cb in callbacks:
            args: list[str] = []
            for ptype in cb.signature.param_types:
                arg_name = f"arg{arg_counter}"
                arg_counter += 1
                locals_.append(Variable(arg_name, _parse_type(ptype)))
                statements.append(
                    Statement(
                        stmt_id=self._fresh_id(),
                        kind="new",
                        lhs=arg_name,
                        rhs=ptype,
                        metadata={"synthetic": True},
                    )
                )
                args.append(arg_name)
            statements.append(
                Statement(
                    stmt_id=self._fresh_id(),
                    kind="call",
                    callee=cb.signature,
                    receiver=None if cb.is_static else component_local,
                    args=args,
                    metadata={"synthetic": True, "lifecycle": cb.name},
                )
            )
            self.callbacks_modelled += 1
        statements.append(
            Statement(stmt_id=self._fresh_id(), kind="return", metadata={"synthetic": True})
        )

        sig = MethodSignature(cls_name, "dummyMainOfComponent", [], "void")
        body = MethodBody(locals=locals_, statements=statements, this_local=None, param_locals=[])
        jimple = JimpleBuilder().build(sig, body)

        decl = _synthetic_method_decl(sig)
        method = SootMethod(decl, self.scene.get_class(cls_name), jimple)
        method.is_static = True
        self.scene.methods[method.full_signature()] = method
        self.components_modelled += 1
        return method


def _synthetic_method_decl(sig: MethodSignature):
    from program_model import Method

    return Method(signature=sig, body=None, is_static=True, is_entry_point=True)


# ---------------------------------------------------------------------------
# IFDS solver
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class Leak:
    """A reported source-to-sink flow."""

    source_stmt: int
    sink_stmt: int
    source_method: str
    sink_method: str
    tainted_path: tuple[str, ...] = ()
    source_category: str = ""
    sink_category: str = ""

    def key(self) -> tuple[int, int, str, str]:
        """The identity used when comparing against ``expected_leaks``."""
        return (self.source_stmt, self.sink_stmt, self.source_method, self.sink_method)

    def to_dict(self) -> dict:
        return {
            "source_stmt": self.source_stmt,
            "sink_stmt": self.sink_stmt,
            "source_method": self.source_method,
            "sink_method": self.sink_method,
            "tainted_path": list(self.tainted_path),
        }

    def __str__(self) -> str:
        path = " -> ".join(self.tainted_path)
        return (
            f"{self.source_method}@{self.source_stmt} ==> "
            f"{self.sink_method}@{self.sink_stmt} [{path}]"
        )


class IFDSSolver:
    """The IFDS tabulation algorithm (Reps-Horwitz-Sagiv).

    Path edges are ``(method, entry_fact, stmt, fact)``. Procedure summaries
    (``end_summary``) plus the ``incoming`` map give full context sensitivity
    without re-analysing a callee per calling context.
    """

    def __init__(self, analysis: "FlowDroidAnalysis") -> None:
        self.analysis = analysis
        self.scene = analysis.scene
        self.flows = analysis.flow_functions
        self.ssm = analysis.source_sink_manager

        self.path_edges: set[tuple[str, TaintAbstraction, int, TaintAbstraction]] = set()
        self.worklist: deque[tuple[str, TaintAbstraction, int, TaintAbstraction]] = deque()
        self.end_summary: dict[tuple[str, TaintAbstraction], set[TaintAbstraction]] = defaultdict(set)
        self.incoming: dict[
            tuple[str, TaintAbstraction], set[tuple[str, TaintAbstraction, int, TaintAbstraction]]
        ] = defaultdict(set)
        #: One representative predecessor per fact, used to rebuild taint paths.
        self.predecessor: dict[tuple[str, int, TaintAbstraction], tuple[str, int, TaintAbstraction]] = {}
        self.leaks: dict[tuple[int, int, str, str], Leak] = {}
        self.propagations = 0

    # -- driver ------------------------------------------------------------
    def solve(self, entry_points: list[SootMethod]) -> list[Leak]:
        for method in entry_points:
            if method.body is None or not method.body.units:
                continue
            start = method.body.units[0].stmt_id
            self._propagate(method.full_signature(), ZERO, start, ZERO, None)

        while self.worklist:
            m, d1, n, d2 = self.worklist.popleft()
            self._process(m, d1, n, d2)

        return sorted(self.leaks.values(), key=lambda l: l.key())

    def _propagate(
        self,
        method: str,
        d1: TaintAbstraction,
        stmt: int,
        d2: TaintAbstraction,
        origin: tuple[str, int, TaintAbstraction] | None,
    ) -> None:
        edge = (method, d1, stmt, d2)
        if edge in self.path_edges:
            return
        self.path_edges.add(edge)
        self.propagations += 1
        key = (method, stmt, d2)
        if origin is not None and key not in self.predecessor and origin != key:
            self.predecessor[key] = origin
        self.worklist.append(edge)

    # -- per-unit processing -----------------------------------------------
    def _process(self, m: str, d1: TaintAbstraction, n: int, d2: TaintAbstraction) -> None:
        method = self.scene.get_method(m)
        if method is None or method.body is None:
            return
        body = method.body
        unit = body.unit_by_id(n)
        if unit is None:
            return
        origin = (m, n, d2)

        if unit.is_invoke():
            self._process_call(m, d1, unit, d2, method, body, origin)
        elif not body.graph.successors(n):
            self._process_exit(m, d1, unit, d2)
        else:
            for out_fact in self.flows.normal(unit, d2, body):
                for succ in body.graph.successors(n):
                    self._propagate(m, d1, succ, out_fact, origin)

    def _process_call(
        self,
        m: str,
        d1: TaintAbstraction,
        unit: JimpleStmt,
        d2: TaintAbstraction,
        method: SootMethod,
        body: JimpleBody,
        origin: tuple[str, int, TaintAbstraction],
    ) -> None:
        n = unit.stmt_id
        self._check_sink(m, unit, d2, body)

        callees = self.analysis.callees_of(m, unit)
        for callee in callees:
            callee_body = callee.body
            if callee_body is None or not callee_body.units:
                continue
            entry = callee_body.units[0].stmt_id
            csig = callee.full_signature()
            for d3 in self.flows.call(unit, d2, body, callee):
                self._propagate(csig, d3, entry, d3, origin)
                self.incoming[(csig, d3)].add((m, d1, n, d2))
                for d4 in sorted(self.end_summary[(csig, d3)], key=str):
                    self._apply_summary(m, d1, unit, d2, body, callee, d4)

        for d3 in self.flows.call_to_return(unit, d2, body, has_callee=bool(callees)):
            for succ in body.graph.successors(n):
                self._propagate(m, d1, succ, d3, origin)

        if not body.graph.successors(n):
            # A call in tail position is also an exit of its method.
            self._process_exit(m, d1, unit, d2)

    def _apply_summary(
        self,
        m: str,
        d1: TaintAbstraction,
        call_unit: JimpleStmt,
        d2: TaintAbstraction,
        body: JimpleBody,
        callee: SootMethod,
        exit_fact: TaintAbstraction,
    ) -> None:
        assert callee.body is not None
        for exit_unit in self._exit_units(callee):
            for d5 in self.flows.ret(exit_unit, exit_fact, call_unit, body, callee):
                for succ in body.graph.successors(call_unit.stmt_id):
                    self._propagate(
                        m, d1, succ, d5, (callee.full_signature(), exit_unit.stmt_id, exit_fact)
                    )

    def _exit_units(self, method: SootMethod) -> list[JimpleStmt]:
        assert method.body is not None
        return [u for u in method.body if not method.body.graph.successors(u.stmt_id)]

    def _process_exit(
        self, m: str, d1: TaintAbstraction, unit: JimpleStmt, d2: TaintAbstraction
    ) -> None:
        method = self.scene.get_method(m)
        if method is None:
            return
        self.end_summary[(m, d1)].add(d2)
        for cm, cd1, cn, cd2 in sorted(self.incoming[(m, d1)], key=lambda x: (x[0], x[2], str(x[3]))):
            caller = self.scene.get_method(cm)
            if caller is None or caller.body is None:
                continue
            call_unit = caller.body.unit_by_id(cn)
            if call_unit is None:
                continue
            for d5 in self.flows.ret(unit, d2, call_unit, caller.body, method):
                for succ in caller.body.graph.successors(cn):
                    self._propagate(cm, cd1, succ, d5, (m, unit.stmt_id, d2))

    # -- sinks -------------------------------------------------------------
    def _check_sink(
        self, m: str, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody
    ) -> None:
        if fact.is_zero or not self.ssm.is_sink(unit):
            return
        flowing = [a for a in unit.args if body.is_local(a) and a == fact.base]
        if unit.receiver is not None and unit.receiver == fact.base:
            flowing.append(unit.receiver)
        if not flowing:
            return
        leak = Leak(
            source_stmt=fact.source_stmt,
            sink_stmt=unit.stmt_id,
            source_method=fact.source_api,
            sink_method=self.ssm.api_name(unit),
            tainted_path=self._reconstruct_path(m, unit.stmt_id, fact),
            source_category=fact.source_category,
            sink_category=self.ssm.sink_category(unit),
        )
        self.leaks.setdefault(leak.key(), leak)

    def _reconstruct_path(
        self, method: str, stmt: int, fact: TaintAbstraction
    ) -> tuple[str, ...]:
        """Walk the predecessor chain back to the source, newest last."""
        chain: list[tuple[str, TaintAbstraction]] = []
        cur: tuple[str, int, TaintAbstraction] | None = (method, stmt, fact)
        seen: set[tuple[str, int, TaintAbstraction]] = set()
        while cur is not None and cur not in seen:
            seen.add(cur)
            chain.append((cur[0], cur[2]))
            cur = self.predecessor.get(cur)

        chain.reverse()
        source_method = fact.source_method
        rendered: list[str] = []
        for owner, f in chain:
            if f.is_zero:
                continue
            label = str(f.access_path)
            if f.is_alias:
                label += "(alias)"
            elif owner != source_method:
                short = self.scene.get_method(owner)
                if short is not None:
                    label += f"({short.signature.method_name})"
            if not rendered or rendered[-1] != label:
                rendered.append(label)
        return tuple(rendered)


