# Analysis driver
# ---------------------------------------------------------------------------


@dataclass
class FlowDroidResult:
    program_name: str
    leaks: list[Leak]
    expected: list[dict]
    true_positives: int
    false_positives: int
    false_negatives: int
    propagations: int
    path_edges: int
    entry_points: int
    components_modelled: int
    callbacks_modelled: int
    elapsed_ms: float
    exact_paths: int = 0

    @property
    def matches_expected(self) -> bool:
        return self.false_positives == 0 and self.false_negatives == 0


class FlowDroidAnalysis:
    """FlowDroid-style taint analysis over one :class:`Program`."""

    def __init__(
        self,
        program: Program,
        taint_wrapper: ITaintWrapper | None = None,
        scene: Scene | None = None,
    ) -> None:
        self.program = program
        self.scene = scene if scene is not None else reset_scene().load_program(program)
        self.source_sink_manager = SourceSinkManager(program)
        self.taint_wrapper: ITaintWrapper = taint_wrapper or DefaultTaintWrapper()
        self.flow_functions = TaintFlowFunctions(self)
        self.call_graph: CallGraph = CHACallGraphBuilder(self.scene).build()
        self.lifecycle = LifecycleModel(self.scene)
        self._alias_cache: dict[str, AliasManager] = {}
        self.solver: IFDSSolver | None = None

    # -- helpers -----------------------------------------------------------
    def alias_manager_for(self, body: JimpleBody) -> AliasManager:
        key = body.signature.full_signature()
        cached = self._alias_cache.get(key)
        if cached is None or cached.body is not body:
            cached = AliasManager(body)
            self._alias_cache[key] = cached
        return cached

    def callees_of(self, method: str, unit: JimpleStmt) -> list[SootMethod]:
        """Concrete call targets with an analysable body at this call site."""
        if unit.callee is None:
            return []
        if self.taint_wrapper.supports_callee(unit.callee) and not isinstance(
            self.taint_wrapper, DefaultTaintWrapper
        ):
            # A summary exists: model the call instead of descending into it.
            return []
        targets: list[SootMethod] = []
        for edge in self.call_graph.edges_out_of_site(method, unit.stmt_id):
            callee = self.scene.get_method(edge.tgt_method)
            if callee is not None and callee.body is not None:
                targets.append(callee)
        if not targets:
            direct = self.scene.get_method(unit.callee)
            if direct is not None and direct.body is not None:
                targets.append(direct)
        return targets

    def entry_points(self) -> list[SootMethod]:
        """Dummy mains for components, plus any standalone entry point."""
        entries: list[SootMethod] = []
        covered: set[str] = set()
        for cls in self.scene.android_components():
            dummy = self.lifecycle.build_dummy_main(cls.name)
            if dummy is None:
                continue
            entries.append(dummy)
            for cb in self.lifecycle.lifecycle_methods_of(cls.name):
                covered.add(cb.full_signature())
        for method in self.scene.get_entry_points():
            if method.full_signature() in covered or method.body is None:
                continue
            entries.append(method)
        return entries

    # -- run ---------------------------------------------------------------
    def run(self) -> FlowDroidResult:
        with Timer() as t:
            entries = self.entry_points()
            self.solver = IFDSSolver(self)
            leaks = self.solver.solve(entries)

        expected = self.program.expected_leaks or []
        expected_keys = {
            (
                e.get("source_stmt"),
                e.get("sink_stmt"),
                e.get("source_method"),
                e.get("sink_method"),
            )
            for e in expected
        }
        found_keys = {l.key() for l in leaks}
        tp = len(found_keys & expected_keys)
        fp = len(found_keys - expected_keys)
        fn = len(expected_keys - found_keys)

        exact = 0
        by_key = {l.key(): l for l in leaks}
        for e in expected:
            key = (
                e.get("source_stmt"),
                e.get("sink_stmt"),
                e.get("source_method"),
                e.get("sink_method"),
            )
            leak = by_key.get(key)
            if leak is not None and list(leak.tainted_path) == list(e.get("tainted_path", [])):
                exact += 1

        return FlowDroidResult(
            program_name=self.program.name,
            leaks=leaks,
            expected=expected,
            true_positives=tp,
            false_positives=fp,
            false_negatives=fn,
            propagations=self.solver.propagations,
            path_edges=len(self.solver.path_edges),
            entry_points=len(entries),
            components_modelled=self.lifecycle.components_modelled,
            callbacks_modelled=self.lifecycle.callbacks_modelled,
            elapsed_ms=t.elapsed_ms,
            exact_paths=exact,
        )


def analyze_program(program: Program, taint_wrapper: ITaintWrapper | None = None) -> FlowDroidResult:
    return FlowDroidAnalysis(program, taint_wrapper=taint_wrapper).run()


