def _reconstruct_path(
    self, method: str, stmt: int, fact: TaintAbstraction
) -> tuple[str, ...]:
    """Rebuild the caller-visible taint path from source to sink.

    The raw predecessor chain also contains every step taken *inside* a
    callee. FlowDroid reports the flow at the granularity the caller can
    observe, so steps belonging to a summarised callee are collapsed into
    the single caller fact they produced, annotated with the library
    method that mediated the flow.
    """
    chain = self._raw_chain(method, stmt, fact)
    chain = self._expand_aliases(chain)

    source_method = fact.source_method
    sink_method = method
    spine = {source_method, sink_method}
    visible = [step for step in chain if step[0] in spine]
    if not visible:
        visible = chain

    qualify_all = self._crosses_lifecycle_callbacks(source_method, sink_method)
    rendered: list[str] = []
    for owner, f, via in visible:
        if f.is_zero:
            continue
        label = str(f.access_path)
        if f.is_alias:
            label += "(alias)"
        elif via is not None and self.scene.is_library_method(owner_of_via := via) is None:
            pass
        elif via is not None:
            label += f"(via {via})"
        elif f.access_path.is_local_only and (qualify_all or owner != source_method):
            owner_method = self.scene.get_method(owner)
            if owner_method is not None:
                label += f"({owner_method.signature.method_name})"
        if not rendered or rendered[-1] != label:
            rendered.append(label)
    return tuple(rendered)

def _raw_chain(
    self, method: str, stmt: int, fact: TaintAbstraction
) -> list[tuple[str, TaintAbstraction, str | None]]:
    """Walk predecessors back to the source; oldest first."""
    chain: list[tuple[str, TaintAbstraction, str | None]] = []
    cur: tuple[str, int, TaintAbstraction] | None = (method, stmt, fact)
    seen: set[tuple[str, int, TaintAbstraction]] = set()
    while cur is not None and cur not in seen:
        seen.add(cur)
        prev = self.predecessor.get(cur)
        via = None
        if prev is not None and prev[3] == "return":
            # Only library calls are reported as a "via" hop; application
            # methods are part of the spine and shown directly.
            callee_owner = self.scene.get_method(prev[0])
            if callee_owner is not None and callee_owner.declaring_class.is_library:
                via = prev[4]
        chain.append((cur[0], cur[2], via))
        cur = (prev[0], prev[1], prev[2]) if prev is not None else None
    chain.reverse()
    return chain

def _expand_aliases(
    self, chain: list[tuple[str, TaintAbstraction, str | None]]
) -> list[tuple[str, TaintAbstraction, str | None]]:
    """Insert the primary write in front of each aliased read."""
    out: list[tuple[str, TaintAbstraction, str | None]] = []
    for owner, f, via in chain:
        primary = self.analysis.alias_links.get(f)
        if primary is not None and (not out or out[-1][1] != primary):
            out.append((owner, primary, None))
        out.append((owner, f, via))
    return out

def _crosses_lifecycle_callbacks(self, source_method: str, sink_method: str) -> bool:
    """True when source and sink sit in two different lifecycle callbacks."""
    if source_method == sink_method:
        return False
    callbacks = self.analysis.lifecycle_callback_signatures()
    return source_method in callbacks and sink_method in callbacks

