"""
StubDroid-style automatic library summaries.

FlowDroid must either analyse library code -- which is huge -- or guess at
its behaviour. StubDroid removes that trade-off by pre-computing a compact
*summary* of every library method: which of its inputs (``this``, its
parameters) flow to which of its outputs (``this``'s fields, its parameters'
fields, the return value). The taint analysis then models a library call by
applying its summary instead of descending into the body.

This module provides:

  * ``SummaryAccessPath``    -- a symbolic (callee-relative) access path
  * ``SummaryFlow``          -- one ``source -> sink`` pair
  * ``MethodSummary``        -- all flows of one method
  * ``SummaryDatabase``      -- signature-keyed store with hierarchy lookup,
                                JSON and StubDroid-style XML serialisation
  * ``SummaryGenerator``     -- derives summaries automatically from bodies
  * ``SummaryTaintWrapper``  -- applies summaries at call sites
  * ``StubDroidAnalysis``    -- the summary-aware taint analysis layer

Run standalone with ``python3 stubdroid_analysis.py``.
"""

from __future__ import annotations

import json
import os
import sys
from collections import defaultdict, deque
from dataclasses import dataclass, field
from typing import Iterable
from xml.etree import ElementTree as ET

from program_model import MethodSignature, Program, load_all_benchmarks
from flowdroid_analysis import (
    AccessPath,
    DefaultTaintWrapper,
    FlowDroidAnalysis,
    FlowDroidResult,
    ITaintWrapper,
    Leak,
    TaintAbstraction,
    format_metrics,
)
from soot_analysis import JimpleBody, JimpleStmt, Scene, SootMethod
from utils import Timer

#: Symbolic bases used by a summary (they are callee-relative, so a summary
#: is independent of the locals any particular caller happens to use).
THIS = "this"
PARAM = "parameter"
RETURN = "return"


# ---------------------------------------------------------------------------
# Summary representation
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class SummaryAccessPath:
    """A callee-relative access path, e.g. ``this._elements`` or ``parameter0``."""

    kind: str  # THIS | PARAM | RETURN
    param_index: int = -1
    fields: tuple[str, ...] = ()

    @staticmethod
    def this(fields: Iterable[str] = ()) -> "SummaryAccessPath":
        return SummaryAccessPath(THIS, -1, tuple(fields))

    @staticmethod
    def parameter(index: int, fields: Iterable[str] = ()) -> "SummaryAccessPath":
        return SummaryAccessPath(PARAM, index, tuple(fields))

    @staticmethod
    def ret(fields: Iterable[str] = ()) -> "SummaryAccessPath":
        return SummaryAccessPath(RETURN, -1, tuple(fields))

    @property
    def base_name(self) -> str:
        if self.kind == PARAM:
            return f"{PARAM}{self.param_index}"
        return self.kind

    def __str__(self) -> str:
        return ".".join((self.base_name,) + self.fields)

    def to_dict(self) -> dict:
        return {"kind": self.kind, "param_index": self.param_index, "fields": list(self.fields)}

    @staticmethod
    def from_dict(d: dict) -> "SummaryAccessPath":
        return SummaryAccessPath(
            kind=d["kind"],
            param_index=d.get("param_index", -1),
            fields=tuple(d.get("fields", [])),
        )

    @staticmethod
    def parse(text: str) -> "SummaryAccessPath":
        """Parse ``"parameter0._elements"`` back into a summary access path."""
        parts = text.split(".")
        base, fields = parts[0], tuple(parts[1:])
        if base == THIS:
            return SummaryAccessPath.this(fields)
        if base == RETURN:
            return SummaryAccessPath.ret(fields)
        if base.startswith(PARAM):
            return SummaryAccessPath.parameter(int(base[len(PARAM):]), fields)
        raise ValueError(f"unrecognised summary access path: {text!r}")


@dataclass(frozen=True)
class SummaryFlow:
    """A single taint flow through a library method."""

    source: SummaryAccessPath
    sink: SummaryAccessPath

    def __str__(self) -> str:
        return f"{self.source} -> {self.sink}"

    def to_dict(self) -> dict:
        return {"from": self.source.to_dict(), "to": self.sink.to_dict()}

    @staticmethod
    def from_dict(d: dict) -> "SummaryFlow":
        return SummaryFlow(
            SummaryAccessPath.from_dict(d["from"]), SummaryAccessPath.from_dict(d["to"])
        )

    @staticmethod
    def parse(text: str) -> "SummaryFlow":
        src, _, dst = text.partition("->")
        return SummaryFlow(
            SummaryAccessPath.parse(src.strip()), SummaryAccessPath.parse(dst.strip())
        )


@dataclass
class MethodSummary:
    """Every taint flow of one library method."""

    signature: str
    class_name: str
    method_name: str
    flows: set[SummaryFlow] = field(default_factory=set)
    is_static: bool = False

    def add(self, flow: SummaryFlow) -> bool:
        before = len(self.flows)
        self.flows.add(flow)
        return len(self.flows) != before

    def sorted_flows(self) -> list[SummaryFlow]:
        return sorted(self.flows, key=str)

    @property
    def is_empty(self) -> bool:
        return not self.flows

    def to_dict(self) -> dict:
        return {
            "signature": self.signature,
            "class_name": self.class_name,
            "method_name": self.method_name,
            "is_static": self.is_static,
            "flows": [f.to_dict() for f in self.sorted_flows()],
        }

    @staticmethod
    def from_dict(d: dict) -> "MethodSummary":
        return MethodSummary(
            signature=d["signature"],
            class_name=d["class_name"],
            method_name=d["method_name"],
            flows={SummaryFlow.from_dict(f) for f in d.get("flows", [])},
            is_static=d.get("is_static", False),
        )

    def __str__(self) -> str:
        return f"{self.signature}: " + ", ".join(str(f) for f in self.sorted_flows())


class SummaryDatabase:
    """Signature-keyed store of :class:`MethodSummary` objects.

    Lookup walks the class hierarchy so a call declared on an interface
    (``java.util.List.add``) still finds the summary computed for the
    implementation that CHA resolved to.
    """

    def __init__(self, scene: Scene | None = None) -> None:
        self.summaries: dict[str, MethodSummary] = {}
        self.scene = scene

    # -- mutation ----------------------------------------------------------
    def put(self, summary: MethodSummary) -> None:
        self.summaries[summary.signature] = summary

    def get_or_create(self, method: SootMethod) -> MethodSummary:
        key = method.full_signature()
        existing = self.summaries.get(key)
        if existing is None:
            existing = MethodSummary(
                signature=key,
                class_name=method.declaring_class.name,
                method_name=method.name,
                is_static=method.is_static,
            )
            self.summaries[key] = existing
        return existing

    # -- lookup ------------------------------------------------------------
    def get(self, signature: MethodSignature | str) -> MethodSummary | None:
        key = signature if isinstance(signature, str) else signature.full_signature()
        direct = self.summaries.get(key)
        if direct is not None:
            return direct
        if self.scene is None or isinstance(signature, str):
            return None
        return self._lookup_via_hierarchy(signature)

    def _lookup_via_hierarchy(self, signature: MethodSignature) -> MethodSummary | None:
        """Try the declared type's subtypes and supertypes."""
        assert self.scene is not None
        hierarchy = self.scene.hierarchy
        if hierarchy is None:
            return None
        candidates = list(hierarchy.subclasses_of(signature.class_name)) + list(
            hierarchy.superclasses_of(signature.class_name)
        )
        for cls_name in sorted(candidates):
            probe = MethodSignature(
                class_name=cls_name,
                method_name=signature.method_name,
                param_types=list(signature.param_types),
                return_type=signature.return_type,
            )
            found = self.summaries.get(probe.full_signature())
            if found is not None:
                return found
        return None

    def has_summary(self, signature: MethodSignature | str) -> bool:
        summary = self.get(signature)
        return summary is not None and not summary.is_empty

    # -- statistics --------------------------------------------------------
    def __len__(self) -> int:
        return len(self.summaries)

    @property
    def total_flows(self) -> int:
        return sum(len(s.flows) for s in self.summaries.values())

    def classes(self) -> list[str]:
        return sorted({s.class_name for s in self.summaries.values()})

    def non_empty(self) -> list[MethodSummary]:
        return [
            self.summaries[k] for k in sorted(self.summaries) if not self.summaries[k].is_empty
        ]

    def all_summaries(self) -> list[MethodSummary]:
        return [self.summaries[k] for k in sorted(self.summaries)]

    # -- persistence -------------------------------------------------------
    def to_json(self) -> str:
        return json.dumps(
            {"summaries": [s.to_dict() for s in self.all_summaries()]}, indent=2, sort_keys=True
        )

    @staticmethod
    def from_json(text: str, scene: Scene | None = None) -> "SummaryDatabase":
        db = SummaryDatabase(scene)
        for entry in json.loads(text).get("summaries", []):
            db.put(MethodSummary.from_dict(entry))
        return db

    def to_xml(self) -> str:
        """Serialise in the shape of StubDroid's per-class summary XML."""
        root = ET.Element("summaries", attrib={"fileFormatVersion": "1"})
        by_class: dict[str, list[MethodSummary]] = defaultdict(list)
        for summary in self.all_summaries():
            by_class[summary.class_name].append(summary)
        for cls_name in sorted(by_class):
            cls_el = ET.SubElement(root, "class", attrib={"name": cls_name})
            methods_el = ET.SubElement(cls_el, "methods")
            for summary in by_class[cls_name]:
                m_el = ET.SubElement(
                    methods_el, "method", attrib={"id": summary.signature}
                )
                flows_el = ET.SubElement(m_el, "flows")
                for flow in summary.sorted_flows():
                    ET.SubElement(
                        flows_el,
                        "flow",
                        attrib={"from": str(flow.source), "to": str(flow.sink)},
                    )
        ET.indent(root, space="  ")
        return ET.tostring(root, encoding="unicode")

    @staticmethod
    def from_xml(text: str, scene: Scene | None = None) -> "SummaryDatabase":
        db = SummaryDatabase(scene)
        root = ET.fromstring(text)
        for cls_el in root.findall("class"):
            cls_name = cls_el.get("name", "")
            for m_el in cls_el.iter("method"):
                sig = m_el.get("id", "")
                summary = MethodSummary(
                    signature=sig,
                    class_name=cls_name,
                    method_name=sig.split(" ")[-1].split("(")[0] if " " in sig else sig,
                )
                for flow_el in m_el.iter("flow"):
                    summary.add(
                        SummaryFlow(
                            SummaryAccessPath.parse(flow_el.get("from", "")),
                            SummaryAccessPath.parse(flow_el.get("to", "")),
                        )
                    )
                db.put(summary)
        return db

    def save(self, path: str) -> None:
        with open(path, "w") as fh:
            fh.write(self.to_xml() if path.endswith(".xml") else self.to_json())

    @staticmethod
    def load(path: str, scene: Scene | None = None) -> "SummaryDatabase":
        with open(path) as fh:
            text = fh.read()
        if path.endswith(".xml"):
            return SummaryDatabase.from_xml(text, scene)
        return SummaryDatabase.from_json(text, scene)


# ---------------------------------------------------------------------------
# Automatic summary generation
# ---------------------------------------------------------------------------


class SummaryGenerator:
    """Derives library summaries automatically from library method bodies.

    For every library method with a body we seed each possible *input*
    location (``this``, each of ``this``'s declared fields, each parameter)
    as tainted, run the same flow functions the taint analysis uses to a
    fixpoint over the method's CFG, and record which *output* locations
    (``this``/parameter fields, the return value) end up tainted.

    Because a library method may call another library method the whole
    process is iterated to a fixpoint, so callee summaries feed into their
    callers.
    """

    def __init__(self, analysis: FlowDroidAnalysis, max_rounds: int = 8) -> None:
        self.analysis = analysis
        self.scene = analysis.scene
        self.flows = analysis.flow_functions
        self.max_rounds = max_rounds
        self.database = SummaryDatabase(self.scene)
        self.rounds = 0
        self.methods_analysed = 0
        self.seeds_evaluated = 0

    # -- entry point -------------------------------------------------------
    def generate(self) -> SummaryDatabase:
        targets = self._library_methods()
        for method in targets:
            self.database.get_or_create(method)

        for _ in range(self.max_rounds):
            self.rounds += 1
            changed = False
            for method in targets:
                if self._summarise(method):
                    changed = True
            if not changed:
                break
        return self.database

    def _library_methods(self) -> list[SootMethod]:
        out = []
        for method in self.scene.all_methods():
            if not method.declaring_class.is_library or method.body is None:
                continue
            if not method.body.units:
                continue
            out.append(method)
        return out

    # -- per-method --------------------------------------------------------
    def _summarise(self, method: SootMethod) -> bool:
        body = method.body
        assert body is not None
        summary = self.database.get_or_create(method)
        changed = False
        self.methods_analysed += 1

        for seed_ap, seed_symbolic in self._seeds(method, body):
            self.seeds_evaluated += 1
            reached = self._propagate(method, body, seed_ap)
            for out_ap, out_symbolic in self._outputs(method, body, reached):
                if out_symbolic == seed_symbolic:
                    continue  # identity flow carries no information
                if summary.add(SummaryFlow(seed_symbolic, out_symbolic)):
                    changed = True
        return changed

    def _seeds(
        self, method: SootMethod, body: JimpleBody
    ) -> list[tuple[AccessPath, SummaryAccessPath]]:
        """Input locations to try as tainted, with their symbolic names."""
        seeds: list[tuple[AccessPath, SummaryAccessPath]] = []
        if body.this_local and not method.is_static:
            seeds.append((AccessPath.of(body.this_local), SummaryAccessPath.this()))
            for f in method.declaring_class.fields:
                seeds.append(
                    (
                        AccessPath.of(body.this_local, [f.name]),
                        SummaryAccessPath.this([f.name]),
                    )
                )
        for idx, param in enumerate(body.param_locals):
            seeds.append((AccessPath.of(param), SummaryAccessPath.parameter(idx)))
        return seeds

    def _outputs(
        self, method: SootMethod, body: JimpleBody, reached: dict[int, set[TaintAbstraction]]
    ) -> list[tuple[AccessPath, SummaryAccessPath]]:
        """Output locations that ended up tainted at some exit of the method."""
        found: dict[str, tuple[AccessPath, SummaryAccessPath]] = {}
        for unit in body:
            if body.graph.successors(unit.stmt_id):
                continue
            for fact in reached.get(unit.stmt_id, set()):
                ap = fact.access_path
                symbolic = self._to_symbolic(method, body, unit, ap)
                if symbolic is not None:
                    found[str(symbolic)] = (ap, symbolic)
        return [found[k] for k in sorted(found)]

    def _to_symbolic(
        self, method: SootMethod, body: JimpleBody, exit_unit: JimpleStmt, ap: AccessPath
    ) -> SummaryAccessPath | None:
        """Translate a callee-local access path into a summary access path."""
        # The returned value.
        if (
            exit_unit.kind == "return"
            and exit_unit.rhs is not None
            and ap.base == exit_unit.rhs
            and body.is_local(exit_unit.rhs)
        ):
            return SummaryAccessPath.ret(ap.fields)
        # Heap state hanging off `this`.
        if body.this_local and ap.base == body.this_local and not method.is_static:
            if not ap.fields:
                return None  # a purely local re-taint of `this` is invisible
            return SummaryAccessPath.this(ap.fields)
        # Heap state hanging off a parameter.
        for idx, param in enumerate(body.param_locals):
            if ap.base == param and ap.fields:
                return SummaryAccessPath.parameter(idx, ap.fields)
        return None

    # -- intra-procedural propagation --------------------------------------
    def _propagate(
        self, method: SootMethod, body: JimpleBody, seed: AccessPath
    ) -> dict[int, set[TaintAbstraction]]:
        """Fixpoint of the taint flow functions over one body."""
        seed_fact = TaintAbstraction(
            access_path=seed,
            source_stmt=-1,
            source_method=method.full_signature(),
            source_api="<summary-seed>",
        )
        facts: dict[int, set[TaintAbstraction]] = defaultdict(set)
        start = body.units[0].stmt_id
        facts[start].add(seed_fact)
        work: deque[tuple[int, TaintAbstraction]] = deque([(start, seed_fact)])

        while work:
            stmt_id, fact = work.popleft()
            unit = body.unit_by_id(stmt_id)
            if unit is None:
                continue
            for out_fact in self._flow(unit, fact, body):
                for succ in body.graph.successors(stmt_id):
                    if out_fact not in facts[succ]:
                        facts[succ].add(out_fact)
                        work.append((succ, out_fact))
        return facts

    def _flow(
        self, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody
    ) -> list[TaintAbstraction]:
        """One statement's transfer function, using summaries for callees."""
        if not unit.is_invoke():
            return self.flows.normal(unit, fact, body)

        out: list[TaintAbstraction] = []
        summary = self.database.get(unit.callee) if unit.callee else None
        if summary is not None and not summary.is_empty:
            out.extend(apply_summary(summary, unit, fact, body))
        else:
            out.extend(DefaultTaintWrapper().get_taints_for_method(unit, fact, body))
        if not (unit.lhs is not None and fact.base == unit.lhs):
            out.append(fact)
        return out


# ---------------------------------------------------------------------------
# Applying summaries at a call site
# ---------------------------------------------------------------------------


def _resolve_base(unit: JimpleStmt, ap: SummaryAccessPath, body: JimpleBody) -> str | None:
    """Map a symbolic base onto the concrete local used at this call site."""
    if ap.kind == THIS:
        return unit.receiver if unit.receiver and body.is_local(unit.receiver) else None
    if ap.kind == RETURN:
        return unit.lhs if unit.lhs and body.is_local(unit.lhs) else None
    if ap.kind == PARAM:
        if 0 <= ap.param_index < len(unit.args):
            arg = unit.args[ap.param_index]
            return arg if body.is_local(arg) else None
    return None


def apply_summary(
    summary: MethodSummary, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody
) -> list[TaintAbstraction]:
    """Apply every matching flow of ``summary`` to ``fact`` at ``unit``.

    A flow fires when the incoming fact's access path is at or below the
    flow's source; the tail beyond the source is carried over to the sink so
    ``this._elements -> return`` maps ``r4._elements.x`` to ``r5.x``.
    """
    out: list[TaintAbstraction] = []
    for flow in summary.sorted_flows():
        src_base = _resolve_base(unit, flow.source, body)
        if src_base is None or fact.base != src_base:
            continue
        if not _fields_match(fact.access_path.fields, flow.source.fields, fact.access_path):
            continue
        tail = fact.access_path.fields[len(flow.source.fields):]
        dst_base = _resolve_base(unit, flow.sink, body)
        if dst_base is None:
            continue
        new_ap = AccessPath.of(
            dst_base, flow.sink.fields + tail, fact.access_path.taint_sub_fields
        )
        out.append(fact.derive(new_ap))
    return out


def _fields_match(
    fact_fields: tuple[str, ...], source_fields: tuple[str, ...], ap: AccessPath
) -> bool:
    """Whether a fact's field chain is covered by a flow's source chain."""
    if len(fact_fields) >= len(source_fields):
        return fact_fields[: len(source_fields)] == source_fields
    # The fact is shorter than the flow source (e.g. the whole object is
    # tainted): only ``.*`` semantics let it match a deeper source.
    return ap.taint_sub_fields and source_fields[: len(fact_fields)] == fact_fields


class SummaryTaintWrapper(ITaintWrapper):
    """Models library calls from a :class:`SummaryDatabase`.

    Calls with a summary are claimed outright (the solver never enters the
    body). Calls without one fall back to the conservative default model so
    unmodelled library code still propagates taint.
    """

    def __init__(self, database: SummaryDatabase, scene: Scene | None = None) -> None:
        self.database = database
        self.scene = scene
        self.fallback = DefaultTaintWrapper()
        self.summary_hits = 0
        self.fallback_hits = 0

    def attach(self, scene: Scene) -> None:
        """Bind to the scene the analysis actually runs on."""
        self.scene = scene
        self.database.scene = scene

    def supports_callee(self, signature: MethodSignature) -> bool:
        return self.database.has_summary(signature)

    def get_taints_for_method(
        self, unit: JimpleStmt, fact: TaintAbstraction, body: JimpleBody
    ) -> list[TaintAbstraction]:
        summary = self.database.get(unit.callee) if unit.callee else None
        if summary is not None and not summary.is_empty:
            self.summary_hits += 1
            return apply_summary(summary, unit, fact, body)
        self.fallback_hits += 1
        return self.fallback.get_taints_for_method(unit, fact, body)


# ---------------------------------------------------------------------------
# Analysis layer
# ---------------------------------------------------------------------------


@dataclass
class StubDroidResult:
    program_name: str
    taint: FlowDroidResult
    baseline: FlowDroidResult
    summaries_total: int
    summaries_non_empty: int
    summary_flows: int
    summary_classes: int
    library_methods_summarised: int
    summarised_call_sites: int
    generation_ms: float
    declared_flows: int = 0
    declared_flows_confirmed: int = 0

    @property
    def matches_expected(self) -> bool:
        return self.taint.matches_expected

    @property
    def propagation_delta(self) -> int:
        return self.baseline.propagations - self.taint.propagations


class StubDroidAnalysis:
    """Summary-aware taint analysis: StubDroid summaries + FlowDroid IFDS."""

    def __init__(self, program: Program) -> None:
        self.program = program
        self.database: SummaryDatabase | None = None
        self.generator: SummaryGenerator | None = None
        self.wrapper: SummaryTaintWrapper | None = None

    def generate_summaries(self) -> SummaryDatabase:
        """Phase 1: derive summaries from the library code in the program."""
        context = FlowDroidAnalysis(self.program)
        self.generator = SummaryGenerator(context)
        self.database = self.generator.generate()
        return self.database

    def run(self) -> StubDroidResult:
        with Timer() as gen_timer:
            database = self.generate_summaries()

        # Baseline: the same analysis without any summaries, for comparison.
        baseline = FlowDroidAnalysis(self.program).run()

        self.wrapper = SummaryTaintWrapper(database)
        analysis = FlowDroidAnalysis(self.program, taint_wrapper=self.wrapper)
        self.wrapper.attach(analysis.scene)
        taint = analysis.run()

        declared, confirmed = self._validate_declared_flows(database)
        return StubDroidResult(
            program_name=self.program.name,
            taint=taint,
            baseline=baseline,
            summaries_total=len(database),
            summaries_non_empty=len(database.non_empty()),
            summary_flows=database.total_flows,
            summary_classes=len(database.classes()),
            library_methods_summarised=len(database.non_empty()),
            summarised_call_sites=analysis.summarised_calls,
            generation_ms=gen_timer.elapsed_ms,
            declared_flows=declared,
            declared_flows_confirmed=confirmed,
        )

    def _validate_declared_flows(self, database: SummaryDatabase) -> tuple[int, int]:
        """Cross-check generated flows against ``summary_flow`` annotations.

        Some benchmarks document the flow a statement represents in its
        metadata; those annotations are never used to build the summaries,
        so agreement is an independent check on the generator.
        """
        declared = confirmed = 0
        for cls in self.program.classes:
            for method in cls.methods:
                if method.body is None:
                    continue
                sig = method.signature.full_signature()
                summary = database.summaries.get(sig)
                for stmt in method.body.statements:
                    text = stmt.metadata.get("summary_flow")
                    if not text:
                        continue
                    declared += 1
                    try:
                        expected = SummaryFlow.parse(text)
                    except (ValueError, IndexError):
                        continue
                    if summary is not None and expected in summary.flows:
                        confirmed += 1
        return declared, confirmed


def analyze_program(program: Program) -> StubDroidResult:
    return StubDroidAnalysis(program).run()


# ---------------------------------------------------------------------------
# Driver
# ---------------------------------------------------------------------------


def _benchmark_dir() -> str:
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), "benchmarks")


def main(argv: list[str] | None = None) -> int:
    argv = list(sys.argv[1:] if argv is None else argv)
    directory = argv[0] if argv else _benchmark_dir()
    programs = load_all_benchmarks(directory)

    print("=== StubDroid Analysis (automatic library summaries) ===")
    print("ANALYSIS_LAYER: stubdroid")
    print(f"PROGRAMS_ANALYZED: {len(programs)}")

    results: list[StubDroidResult] = []
    for program in programs:
        res = analyze_program(program)
        results.append(res)
        name = res.program_name
        print(f"--- {name} ---")
        print(f"{name}_SUMMARIES_GENERATED: {res.summaries_total}")
        print(f"{name}_SUMMARIES_NON_EMPTY: {res.summaries_non_empty}")
        print(f"{name}_SUMMARY_FLOWS: {res.summary_flows}")
        print(f"{name}_SUMMARY_CLASSES: {res.summary_classes}")
        print(f"{name}_SUMMARISED_CALL_SITES: {res.summarised_call_sites}")
        print(f"{name}_LEAKS_FOUND: {len(res.taint.leaks)}")
        print(f"{name}_LEAKS_EXPECTED: {len(res.taint.expected)}")
        print(f"{name}_TRUE_POSITIVES: {res.taint.true_positives}")
        print(f"{name}_FALSE_POSITIVES: {res.taint.false_positives}")
        print(f"{name}_FALSE_NEGATIVES: {res.taint.false_negatives}")
        print(f"{name}_IFDS_PROPAGATIONS: {res.taint.propagations}")
        print(f"{name}_BASELINE_PROPAGATIONS: {res.baseline.propagations}")
        print(f"{name}_PROPAGATION_DELTA: {res.propagation_delta}")
        print(f"{name}_MATCHES_EXPECTED: {res.matches_expected}")
        for i, leak in enumerate(res.taint.leaks):
            print(f"{name}_LEAK_{i}: {leak}")

    tp = sum(r.taint.true_positives for r in results)
    fp = sum(r.taint.false_positives for r in results)
    fn = sum(r.taint.false_negatives for r in results)
    precision, recall, f1 = format_metrics(tp, fp, fn)
    passed = sum(1 for r in results if r.matches_expected)
    declared = sum(r.declared_flows for r in results)
    confirmed = sum(r.declared_flows_confirmed for r in results)

    print("--- summary database ---")
    print(f"TOTAL_SUMMARIES_GENERATED: {sum(r.summaries_total for r in results)}")
    print(f"TOTAL_SUMMARIES_NON_EMPTY: {sum(r.summaries_non_empty for r in results)}")
    print(f"TOTAL_SUMMARY_FLOWS: {sum(r.summary_flows for r in results)}")
    print(f"TOTAL_SUMMARY_CLASSES: {sum(r.summary_classes for r in results)}")
    print(f"TOTAL_SUMMARISED_CALL_SITES: {sum(r.summarised_call_sites for r in results)}")
    print(f"DECLARED_SUMMARY_FLOWS: {declared}")
    print(f"DECLARED_SUMMARY_FLOWS_CONFIRMED: {confirmed}")
    print("--- taint results ---")
    print(f"TOTAL_LEAKS_FOUND: {sum(len(r.taint.leaks) for r in results)}")
    print(f"TOTAL_LEAKS_EXPECTED: {sum(len(r.taint.expected) for r in results)}")
    print(f"TOTAL_TRUE_POSITIVES: {tp}")
    print(f"TOTAL_FALSE_POSITIVES: {fp}")
    print(f"TOTAL_FALSE_NEGATIVES: {fn}")
    print(f"PRECISION: {precision:.4f}")
    print(f"RECALL: {recall:.4f}")
    print(f"F1_SCORE: {f1:.4f}")
    print(f"BENCHMARKS_PASSED: {passed}")
    print(f"BENCHMARKS_TOTAL: {len(results)}")
    print(f"TOTAL_IFDS_PROPAGATIONS: {sum(r.taint.propagations for r in results)}")
    print(f"TOTAL_BASELINE_PROPAGATIONS: {sum(r.baseline.propagations for r in results)}")
    print(f"TOTAL_PROPAGATION_DELTA: {sum(r.propagation_delta for r in results)}")
    print(f"TOTAL_SUMMARY_GENERATION_MS: {sum(r.generation_ms for r in results):.3f}")
    print(f"TOTAL_ANALYSIS_MS: {sum(r.taint.elapsed_ms for r in results):.3f}")
    print(f"STUBDROID_ANALYSIS_STATUS: {'OK' if passed == len(results) else 'MISMATCH'}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

