def _seeds(
    self, method: SootMethod, body: JimpleBody
) -> list[tuple[AccessPath, SummaryAccessPath]]:
    """Input locations to try as tainted, with their symbolic names.

    Base-object seeds (``this``, ``parameter0`` ...) are seeded *without*
    ``.*`` semantics: a tainted reference does not imply tainted fields.
    Field-level flows come from the explicit per-field seeds below
    instead. Seeding the base with ``.*`` would make any field read look
    like the object itself flowing out, which turns ``get()`` into a
    bogus ``this -> return`` structural flow.
    """
    seeds: list[tuple[AccessPath, SummaryAccessPath]] = []
    if body.this_local and not method.is_static:
        seeds.append(
            (
                AccessPath.of(body.this_local, (), taint_sub_fields=False),
                SummaryAccessPath.this(),
            )
        )
        for f in method.declaring_class.fields:
            seeds.append(
                (
                    AccessPath.of(body.this_local, [f.name]),
                    SummaryAccessPath.this([f.name]),
                )
            )
    for idx, param in enumerate(body.param_locals):
        seeds.append(
            (
                AccessPath.of(param, (), taint_sub_fields=False),
                SummaryAccessPath.parameter(idx),
            )
        )
        for f in self._fields_of_local_type(body, param):
            seeds.append(
                (
                    AccessPath.of(param, [f]),
                    SummaryAccessPath.parameter(idx, [f]),
                )
            )
    return seeds

def _fields_of_local_type(self, body: JimpleBody, local_name: str) -> list[str]:
    """Declared field names of a local's static type, if it is known."""
    local = body.local_by_name(local_name)
    if local is None:
        return []
    cls = self.scene.get_class(local.type_name)
    if cls is None:
        return []
    return [f.name for f in cls.fields]

