"""Tests for the StubDroid layer: summary generation, storage, wrapper, analysis."""

import json
import os
import sys
import tempfile
import unittest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from program_model import load_program
from flowdroid_analysis import AccessPath, FlowDroidAnalysis, TaintAbstraction
from soot_analysis import reset_scene
from stubdroid_analysis import (
    MethodSummary,
    StubDroidAnalysis,
    SummaryAccessPath,
    SummaryDatabase,
    SummaryFlow,
    SummaryGenerator,
    SummaryTaintWrapper,
    analyze_program,
    apply_summary,
)

BENCH = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "benchmarks")

ARRAYLIST_ADD = "<java.util.ArrayList: boolean add(java.lang.Object)>"
ARRAYLIST_GET = "<java.util.ArrayList: java.lang.Object get(int)>"
HASHMAP_PUT = "<java.util.HashMap: java.lang.Object put(java.lang.Object, java.lang.Object)>"
HASHMAP_GET = "<java.util.HashMap: java.lang.Object get(java.lang.Object)>"


def load(name):
    return load_program(os.path.join(BENCH, name))


class TestSummaryAccessPath(unittest.TestCase):
    def test_rendering(self):
        self.assertEqual(str(SummaryAccessPath.this(["_elements"])), "this._elements")
        self.assertEqual(str(SummaryAccessPath.parameter(0)), "parameter0")
        self.assertEqual(str(SummaryAccessPath.parameter(2, ["f"])), "parameter2.f")
        self.assertEqual(str(SummaryAccessPath.ret()), "return")

    def test_round_trip_parse(self):
        for text in ("this", "this._elements", "parameter0", "parameter3.a.b", "return"):
            self.assertEqual(str(SummaryAccessPath.parse(text)), text)

    def test_round_trip_dict(self):
        ap = SummaryAccessPath.parameter(1, ["x", "y"])
        self.assertEqual(SummaryAccessPath.from_dict(ap.to_dict()), ap)

    def test_rejects_garbage(self):
        with self.assertRaises(ValueError):
            SummaryAccessPath.parse("bogus.thing")

    def test_hashable_and_equal(self):
        self.assertEqual(
            {SummaryAccessPath.this(["f"])}, {SummaryAccessPath.this(["f"]), SummaryAccessPath.this(["f"])}
        )


class TestSummaryFlow(unittest.TestCase):
    def test_rendering_and_parse(self):
        flow = SummaryFlow.parse("parameter0 -> this._elements")
        self.assertEqual(str(flow), "parameter0 -> this._elements")
        self.assertEqual(flow.source, SummaryAccessPath.parameter(0))
        self.assertEqual(flow.sink, SummaryAccessPath.this(["_elements"]))

    def test_round_trip_dict(self):
        flow = SummaryFlow.parse("this._values -> return")
        self.assertEqual(SummaryFlow.from_dict(flow.to_dict()), flow)


class TestSummaryGeneration(unittest.TestCase):
    """The generator must derive flows from bodies alone, with no hints."""

    @classmethod
    def setUpClass(cls):
        program = load("06_library_summary.json")
        cls.db = SummaryGenerator(FlowDroidAnalysis(program)).generate()

    def test_arraylist_add_flow(self):
        flows = {str(f) for f in self.db.summaries[ARRAYLIST_ADD].flows}
        self.assertEqual(flows, {"parameter0 -> this._elements"})

    def test_arraylist_get_flow(self):
        flows = {str(f) for f in self.db.summaries[ARRAYLIST_GET].flows}
        self.assertEqual(flows, {"this._elements -> return"})

    def test_hashmap_put_flows_both_params(self):
        # Derived with no summary_flow metadata present at all.
        flows = {str(f) for f in self.db.summaries[HASHMAP_PUT].flows}
        self.assertEqual(flows, {"parameter0 -> this._keys", "parameter1 -> this._values"})

    def test_hashmap_get_reads_values_not_keys(self):
        flows = {str(f) for f in self.db.summaries[HASHMAP_GET].flows}
        self.assertEqual(flows, {"this._values -> return"})

    def test_constructors_have_no_flows(self):
        ctor = self.db.summaries["<java.util.ArrayList: void <init>()>"]
        self.assertTrue(ctor.is_empty)

    def test_no_spurious_structural_flow(self):
        # get() returns an element, not the list: "this -> return" would be wrong.
        flows = {str(f) for f in self.db.summaries[ARRAYLIST_GET].flows}
        self.assertNotIn("this -> return", flows)

    def test_only_library_methods_summarised(self):
        for sig in self.db.summaries:
            self.assertTrue(sig.startswith("<java.util."), sig)

    def test_application_code_not_summarised(self):
        self.assertFalse(any("com.example" in s for s in self.db.summaries))

    def test_generation_reaches_fixpoint(self):
        gen = SummaryGenerator(FlowDroidAnalysis(load("06_library_summary.json")))
        gen.generate()
        self.assertLess(gen.rounds, gen.max_rounds)
        self.assertGreater(gen.seeds_evaluated, 0)

    def test_deterministic(self):
        again = SummaryGenerator(FlowDroidAnalysis(load("06_library_summary.json"))).generate()
        self.assertEqual(again.to_json(), self.db.to_json())

    def test_programs_without_library_bodies_yield_nothing(self):
        db = SummaryGenerator(FlowDroidAnalysis(load("01_simple_flow.json"))).generate()
        self.assertEqual(len(db), 0)


class TestSummaryDatabase(unittest.TestCase):
    def setUp(self):
        self.db = SummaryGenerator(
            FlowDroidAnalysis(load("06_library_summary.json"))
        ).generate()

    def test_counts(self):
        self.assertEqual(len(self.db), 6)
        self.assertEqual(self.db.total_flows, 5)
        self.assertEqual(self.db.classes(), ["java.util.ArrayList", "java.util.HashMap"])
        self.assertEqual(len(self.db.non_empty()), 4)

    def test_has_summary(self):
        self.assertTrue(self.db.has_summary(ARRAYLIST_ADD))
        self.assertFalse(self.db.has_summary("<java.util.ArrayList: void <init>()>"))
        self.assertFalse(self.db.has_summary("<no.Such: void m()>"))

    def test_json_round_trip(self):
        restored = SummaryDatabase.from_json(self.db.to_json())
        self.assertEqual(restored.to_json(), self.db.to_json())
        self.assertEqual(restored.total_flows, self.db.total_flows)

    def test_json_is_valid_and_sorted(self):
        data = json.loads(self.db.to_json())
        sigs = [s["signature"] for s in data["summaries"]]
        self.assertEqual(sigs, sorted(sigs))

    def test_xml_round_trip(self):
        restored = SummaryDatabase.from_xml(self.db.to_xml())
        self.assertEqual(restored.total_flows, self.db.total_flows)
        self.assertEqual(
            {str(f) for f in restored.summaries[ARRAYLIST_ADD].flows},
            {str(f) for f in self.db.summaries[ARRAYLIST_ADD].flows},
        )

    def test_save_and_load_json(self):
        with tempfile.TemporaryDirectory() as d:
            path = os.path.join(d, "summaries.json")
            self.db.save(path)
            self.assertEqual(SummaryDatabase.load(path).total_flows, self.db.total_flows)

    def test_save_and_load_xml(self):
        with tempfile.TemporaryDirectory() as d:
            path = os.path.join(d, "summaries.xml")
            self.db.save(path)
            self.assertEqual(SummaryDatabase.load(path).total_flows, self.db.total_flows)

    def test_hierarchy_lookup(self):
        from program_model import MethodSignature

        scene = reset_scene().load_program(load("06_library_summary.json"))
        self.db.scene = scene
        # A call declared on a supertype should still find ArrayList's summary.
        scene.get_class("java.util.ArrayList").super_class = "java.util.AbstractList"
        scene.hierarchy = type(scene.hierarchy)(scene)
        probe = MethodSignature("java.util.AbstractList", "add", ["java.lang.Object"], "boolean")
        self.assertIsNotNone(self.db.get(probe))

    def test_unknown_lookup_returns_none(self):
        from program_model import MethodSignature

        self.assertIsNone(self.db.get(MethodSignature("no.Such", "m", [], "void")))


class TestApplySummary(unittest.TestCase):
    def setUp(self):
        program = load("06_library_summary.json")
        scene = reset_scene().load_program(program)
        self.body = scene.get_method(
            "<com.example.LibrarySummaryActivity: void onCreate(android.os.Bundle)>"
        ).body
        self.db = SummaryGenerator(FlowDroidAnalysis(program)).generate()

    def test_add_maps_argument_into_receiver_field(self):
        unit = self.body.unit_by_id(4)  # r4.add(r3)
        fact = TaintAbstraction(access_path=AccessPath.of("r3"))
        out = apply_summary(self.db.summaries[ARRAYLIST_ADD], unit, fact, self.body)
        self.assertEqual([str(f.access_path) for f in out], ["r4._elements"])

    def test_get_maps_receiver_field_to_result(self):
        unit = self.body.unit_by_id(5)  # r5 = r4.get(0)
        fact = TaintAbstraction(access_path=AccessPath.of("r4", ["_elements"]))
        out = apply_summary(self.db.summaries[ARRAYLIST_GET], unit, fact, self.body)
