        # Derived with no summary_flow metadata present at all.
        flows = {str(f) for f in self.db.summaries[HASHMAP_PUT].flows}
        self.assertEqual(flows, {"parameter0 -> this._keys", "parameter1 -> this._values"})

    def test_hashmap_get_reads_values_not_keys(self):
        flows = {str(f) for f in self.db.summaries[HASHMAP_GET].flows}
        self.assertEqual(flows, {"this._values -> return"})

