        self.assertGreater(gen.seeds_evaluated, 0)

    def test_deterministic(self):
        again = SummaryGenerator(FlowDroidAnalysis(load("06_library_summary.json"))).generate()
        self.assertEqual(again.to_json(), self.db.to_json())

