def goto(sid, target):
    """The model has no goto, so use an if whose branches both converge."""
    return {"stmt_id": sid, "kind": "if", "condition": "1 == 1",
            "true_target": target, "false_target": target}


class TestBranching(unittest.TestCase):
    """A real diamond: only one arm taints, and the merge must preserve it."""

    def _diamond(self, taint_arm=True):
        #  3: if c goto 6            6: rt = rs      (tainted arm)
        #  4: rt = "safe"            7: sink(rt)
        #  5: goto 7
        arm = ({"stmt_id": 6, "kind": "assign", "lhs": "rt", "rhs": "rs", "rhs_vars": ["rs"]}
               if taint_arm else
               {"stmt_id": 6, "kind": "assign", "lhs": "rt", "rhs": '"also_safe"'})
        stmts = [
            {"stmt_id": 0, "kind": "identity", "lhs": "r0", "rhs": "@this"},
            {"stmt_id": 1, "kind": "identity", "lhs": "r1", "rhs": "@parameter0"},
            src_call(2, "rs"),
